(window.GIM_TS=window.GIM_TS||{})["Bava Batra.6"]={"from":144,"a":[["\u0003וגנו אפרקיד\u0004 \u0005[ושוכבים פרקדן\u0006 על גבם\u0005],\u0006 \u0003והוה זקיפא ברכיה דחד מינייהו\u0004 \u0005[והיתה זקופה ברכו של אחד מהם],\u0006 \u0003ועיל טייעא תותי ברכיה כי רכיב גמלא וזקיפא רומחיה\u0004 \u0005[ונכנס ערבי תחת ברכו כאשר\u0006 הוא \u0005רוכב על גמלו ורומחו זקוף\u0006 בידו\u0005]\u0006 \u0003ולא נגע ביה\u0004 \u0005[בו]\u0006 מרוב גודלו. \u0003פסקי חדא קרנא דתכלתא דחד מינייהו\u0004 \u0005[חתכתי קרן,\u0006 פינה, \u0005אחת של תכלת,\u0006 קצה טלית ובו ציצית, \u0005של אחד מהם],\u0006 \u0003ולא הוה מסתגי לן\u0004 \u0005[היינו יכולים ללכת].\u0006 \u0003אמר לי\u0004 הערבי: \u0003דלמא שקלת מידי מינייהו\u0004 \u0005[שמא לקחת דבר מהם]?\u0006 \u0003אהדריה\u0004 \u0005[החזר אותו],\u0006 \u0003דגמירי דמאן דשקיל מידי מינייהו לא מסתגי ליה\u0004 \u0005[שאנו יודעים במסורת שמי שלוקח דבר מהם אינו יכול ללכת].\u0006 \u0003אזלי אהדרתיה, והדר מסתגי לן\u0004 \u0005[הלכתי החזרתי אותו,\u0006 את קצה הטלית \u0005ואחר כך יכולים היינו ללכת].\u0006","ומוסיף רבה בר בר חנה: \u0003כי אתאי לקמיה\u0004 \u0003דרבנן\u0004 \u0005[כאשר באתי לפני החכמים]\u0006 וסיפרתי להם זאת, \u0003אמרו לי\u0004 בנזיפה: \u0003כל \"אבא\"\u0004 — \u0003חמרא\u0004 \u0005[חמור\u0006 הוא\u0005],\u0006 \u0003וכל \"בר בר חנה\"\u0004 — \u0003סיכסא\u0004 \u0005[שוטה]!\u0006 \u0003למאי הלכתא עבדת הכי\u0004 \u0005[למה,\u0006 לצורך איזו \u0005הלכה עשית כך]\u0006 לחתוך את הציצית? \u0003למידע\u0004 \u0003אי\u0004 \u0005[לדעת אם]\u0006 הלכה \u0003כבית שמאי אי\u0004 \u0005[אם]\u0006 \u0003כבית הלל\u0004 בענין זה? \u0003איבעי\u0004 \u0005[היה]\u0006 \u0003לך למימני\u0004 \u0005[למנות]\u0006 \u0003חוטין ולמימני\u0004 \u0005[ולמנות]\u0006 \u0003חוליות\u0004 ולא היית צריך לקחת.","ועוד \u0003אמר לי\u0004 אותו ערבי: \u0003תא אחוי\u0004 \u0005[בוא\u0006 ו\u0005אראה]\u0006 \u0003לך\u0004 את \u0003הר סיני. אזלי, חזאי דהדרא ליה עקרבא וקיימא כי חמרי חוורתי\u0004 \u0005[הלכתי,\u0006 באתי ו\u0005ראיתי שמקיפים אותו עקרבים ו\u0006הם \u0005עומדים\u0006 וקומתם \u0005כמו חמורים לבנים].\u0006 \u0003שמעתי בת קול שאומרת: \"אוי לי שנשבעתי\u0004 להגלות את ישראל, \u0003ועכשיו שנשבעתי מי מפר לי\"?\u0004","\u0003כי אתאי לקמיה\u0004 \u0003דרבנן\u0004 \u0005[כאשר באתי לפני חכמים]\u0006 וסיפרתי להם זאת, \u0003אמרו לי\u0004 בנזיפה: \u0003כל \"אבא\"\u0004 — \u0003חמרא\u0004 \u0005[חמור\u0006 הוא\u0005],\u0006 \u0003כל \"בר בר חנה\"\u0004 — \u0003סיכסא\u0004 \u0005[שוטה]!\u0006 \u0003היה לך לומר \"מופר לך\".\u0004 ומסבירים: \u0003והוא\u0004 רבה בר בר חנה שלא היפר, משום ש\u0003סבר:\u0004 \u0003דלמא שבועתא\u0004 \u0005[שמא שבועת]\u0006 ה\u0003מבול הוא\u0004 \u0005[היא],\u0006 שנשבע הקדוש ברוך הוא שלא יביא מבול לעולם, ולכן לא רצה להפר. \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה סבורים? \u0003אם כן,\u0004 אם היתה זו שבועת המבול \u0003\"אוי לי\" למה?\u0004 אלא ודאי היתה זו שבועה על גלות ישראל.","ומוסיף רבה בר בר חנה, ועוד \u0003אמר לי\u0004 אותו ערבי: \u0003תא אחוי\u0004 \u0005[בוא\u0006 ו\u0005אראה]\u0006 \u0003לך\u0004 את \u0003בלועי\u0004 \u0005[הנבלעים]\u0006 באדמה בחטא \u0003קרח.\u0004 \u0003חזאי תרי ביזעי והוו קא מפקי קוטרא\u0004 \u0005[ראיתי שני בקעים\u0006 באדמה \u0005שהיו מוציאים עשן].\u0006 \u0003שקל גבבא דעמרא ואמשינה במיא\u0004 \u0005[לקח\u0006 אותו ערבי \u0005גיזת צמר וטבל אותה במים]\u0006 \u0003ודעציתה בראשה דרומחא ועייליה התם\u0004 \u0005[ונעץ אותה בראשו של רומח והכניס אותו לשם],\u0006 \u0003וכי אפיק, הוה איחרך איחרוכי\u0004 \u0005[וכאשר הוציא\u0006 אותו \u0005היה\u0006 הצמר \u0005חרוך].\u0006 \u0003אמר לי: אצית מאי שמעת\u0004 \u0005[הקשב מה אתה שומע],\u0006 \u0003ושמעית דהוו אמרין\u0004 \u0005[ושמעתי שהיו אומרים]:\u0006 \u0003\"משה ותורתו אמת והן\u0004 עצמם \u0003בדאין\u0004 (שקרנים) \u0003\".\u0004 \u0003אמר לי: כל תלתין יומי\u0004 \u0005[שלושים יום]\u0006 \u0003מהדר להו\u0004 \u0005[מחזיר אותם]\u0006 ה\u0003גיהנם להכא\u0004 \u0005[לכאן]\u0006 \u0003כבשר\u0004 המתבשל \u0003בקלחת\u0004 (סיר) שהמים שבתוכה רותחים ומטלטלים את הבשר ממקום למקום, \u0003ואמרי הכי\u0004 \u0005[ואומרים כך]:\u0006 \u0003\"משה ותורתו אמת והן בדאין\".\u0004","ועוד \u0003אמר לי\u0004 אותו ערבי: \u0003תא אחוי\u0004 \u0005[בוא\u0006 ו\u0005אראה]\u0006 \u0003לך היכא דנשקי ארעא ורקיעא אהדדי\u0004 \u0005[היכן שנוגעים הארץ והרקיע זה בזה].\u0006 \u0003שקלתא לסילתאי אתנחתא בכוותא דרקיעא\u0004 \u0005[לקחתי את הסל שלי, הנחתי אותו בחלון שברקיע].\u0006 \u0003אדמצלינא, בעיתיה\u0004 \u0005[עד שהתפללתי, חיפשתי אותו]\u0006 \u0003ולא אשכחיתה\u0004 \u0005[מצאתי אותו].\u0006 \u0003אמינא ליה\u0004 \u0005[אמרתי לו]:\u0006 \u0003איכא גנבי הכא\u0004 \u0005[יש גנבים כאן]?\u0006 \u0003אמר לי: האי גלגלא דרקיעא הוה דהדר\u0004 \u0005[זהו גלגל הרקיע שמסתובב]\u0006 ובו קבוע החלון ובו הסל, \u0003נטר\u0004 \u0005[המתן]\u0006 \u0003עד למחר הכא ומשכחת לה\u0004 \u0005[כאן ותמצא אותו].\u0006","\u0003ר' יוחנן משתעי\u0004 \u0005[\u0006היה \u0005מספר]:\u0006 \u0003זימנא חדא הוה קא אזלינן בספינתא\u0004 \u0005[פעם אחת היינו הולכים בספינה],\u0006 \u0003וחזינן ההוא כוורא דאפקיה לרישיה מימא\u0004 \u0005[וראינו דג אחד שהוציא את ראשו מן הים],\u0006 \u0003ודמיין עייניה כתרי סיהרי\u0004 \u0005[והיו עיניו דומות כשני ירחים],\u0006 \u0003ונפוץ מיא מתרתי זימיה כתרי מברי\u0004 \u0005[ויצאו מים משני הזימים שלו כשני הנהרות]\u0006 שב\u0003סורא.\u0004 \u0003רב ספרא משתעי\u0004 \u0005[\u0006היה \u0005מספר]:\u0006 \u0003זימנא חדא הוה קא אזלינן בספינתא\u0004 \u0005[פעם אחת היינו הולכים בספינה],\u0006 \u0003וחזינן ההוא כוורא דאפקיה לרישיה מימא\u0004 \u0005[וראינו דג אחד שהוציא את ראשו מן הים],\u0006 \u0003והוה ליה קרני וחקיק עליה\u0004 \u0005[והיו לו קרנים והיה חקוק עליו]:\u0006 \u0003\"אנא\u0004 \u0005[אני]\u0006 \u0003בריה קלה שבים\",\u0004 כלומר, מהדברים הקטנים שבים, \u0003\"והוינא תלת מאה פרסי\u0004 \u0005[והייתי,\u0006 גודלי היה \u0005שלוש מאות פרסות],\u0006 \u0003ואזילנא לפומא\u0004 \u0005[ואני הולך לפיו]\u0006 של ה\u0003לויתן\u0004 למזונו\u0003\".\u0004 \u0003אמר רב אשי: ההוא עיזא דימא\u0004 \u0005[זה עז הים]\u0006 \u0003הוא, דבחישא\u0004 \u0005[ש\u0006היא \u0005בוחשת]\u0006 וחופרת בים \u0003ואית\u0004 \u0005[ויש]\u0006 \u0003לה קרני\u0004 \u0005[קרנים].\u0006","\u0003ר' יוחנן משתעי\u0004 \u0005[\u0006היה \u0005מספר]:\u0006 \u0003זימנא חדא הוה קא אזלינן בספינתא\u0004 \u0005[פעם אחת היינו הולכים בספינה],\u0006 \u0003וחזינן ההיא קרטליתא דהוו קא מקבעי בה\u0004 \u0005[וראינו ארגז אחד שהיו קבועות בו]\u0006 \u0003אבנים טובות ומרגליות, והדרי לה מיני דכוורי דמקרי כרשא\u0004 \u0005[וסובבהו מיני דגים שנקראים כרישים].\u0006 \u0003נחית\u0004"],["\u0003בר אמוראי לאתויה\u0004 \u0005[ירד אמודאי להביא אותו]\u0006 את הארגז הזה, \u0003ורגש\u0004 \u0005[ורגז]\u0006 הדג \u0003ובעי לשמטיה לאטמיה\u0004 \u0005[ורצה לשמוט,\u0006 לקטוע \u0005את ירכו],\u0006 \u0003ושדא זיקא דחלא ונחת\u0004 \u0005[וזרק\u0006 אותו אמודאי לעברו \u0005נאד חומץ וירד\u0006 הדג וברח\u0005].\u0006 \u0003נפק בת קלא אמר לן\u0004 \u0005[יצתה בת קול\u0006 ו\u0005אמרה לנו]:\u0006 \u0003מאי אית לכו בהדי קרטליתא דדביתהו\u0004 \u0005[מה יש לכם עם אותו ארגז של אשתו]\u0006 של \u0003ר' חנינא בן דוסא,\u0004 שהיא \u0003עתידה דשדיא תכלתא\u0004 \u0005[לשים תכלת]\u0006 \u0003בה לצדיקי לעלמא דאתי\u0004 \u0005[לצדיקים לעולם הבא]!\u0006","ובענין אבנים טובות \u0003רב יהודה הינדוא\u0004 \u0005[מהודו]\u0006 \u0003משתעי\u0004 \u0005[\u0006היה \u0005מספר]:\u0006 \u0003זימנא חדא הוה אזלינן בספינתא\u0004 \u0005[פעם אחת היינו הולכים בספינה]\u0006 \u0003וחזינן ההוא אבן טבא דהוה הדיר לה תנינא\u0004 \u0005[וראינו אבן טובה שהיה מסובב אותה תנין],\u0006 \u0003נחית בר אמוראי לאתויה\u0004 \u0005[ירד אמודאי להביא אותה].\u0006 \u0003אתא תנינא קא בעי למבלע לה לספינתא\u0004 \u0005[בא התנין ורצה לבלוע את הספינה],\u0006 \u0003אתא פישקנצא פסקיה לרישיה\u0004 \u0005[בא עורב\u0006 ו\u0005חתך את ראשו\u0006 של התנין\u0005],\u0006 \u0003אתהפיכו מיא והוו דמא\u0004 \u0005[הפכו המים ונעשו דם]\u0006 מרוב גודלו של התנין, \u0003אתא תנינא חבריה שקליה ותליה ליה וחיה\u0004 \u0005[בא תנין\u0006 אחר \u0005חבירו לקחו\u0006 את האבן \u0005ותלה בו\u0006 בתנין ההרוג \u0005וחיה].\u0006 \u0003הדר אתא קא בעי בלעא לספינתא\u0004 \u0005[חזר\u0006 ו\u0005בא\u0006 ו\u0005רצה לבלוע את הספינה],\u0006 \u0003הדר אתא ציפרא פסקיה לרישיה\u0004 \u0005[חזרה\u0006 ו\u0005באה הציפור\u0006 ו\u0005חתכה את ראשו],\u0006 \u0003שקלוה לההיא אבן טבא שדיוה לספינתא\u0004 \u0005[לקחו את האבן הטובה הזו\u0006 ו\u0005זרקו אותה לספינה],\u0006 \u0003הוה הני ציפרי מליחי בהדן\u0004 \u0005[היו לנו ציפורים מלוחות איתנו],\u0006 \u0003אותבינהו עלייהו\u0004 \u0005[שמנו אותה\u0006 את האבן \u0005עליהם],\u0006 \u0003שקלוה ופרחו להו בהדה\u0004 \u0005[לקחו\u0006 את האבן \u0005ועפו להם יחד איתה].\u0006","ובענין יצורים גדולים שבים, עוסקים באלו שנזכרו במקרא. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מעשה בר' אליעזר ור' יהושע שהיו באין בספינה, והיה ר' אליעזר ישן ור' יהושע נעור. נזדעזע ר' יהושע וננער ר' אליעזר. אמר לו\u0004 ר' אליעזר לר' יהושע: \u0003מה זה יהושע, מפני מה נזדעזעת? אמר לו: מאור גדול ראיתי ב\u0004תוך ה\u0003ים. אמר לו: שמא עיניו של לויתן ראית, דכתיב\u0004 \u0005[שנאמר]\u0006 בו: \u0003\"\u0004ו\u0003עיניו כעפעפי שחר\"\u0004 (איוב מא, י).","\u0003אמר רב אשי, אמר לי הונא בר נתן: זימנא חדא הוה קא אזלינן במדברא\u0004 \u0005[פעם אחת היינו מהלכים במדבר],\u0006 \u0003והואי אטמא דבשרא בהדן\u0004 \u0005[והיה ירך של בשר איתנו],\u0006 \u0003פתחנא ונקירנא ואנחנא אעשבי\u0004 \u0005[פתחנו\u0006 את הירך \u0005וניקרנו\u0006 את גיד הנשה והחלב, \u0005והנחנו עשבים\u0006 עליה\u0005],\u0006 \u0003אדמייתינן ציבי חלם אטמא\u0004 \u0005[עד שהבאנו עצים נתרפאה הירך],\u0006 \u0003וטוינן\u0004 \u0005[וצלינו\u0006 אותה\u0005].\u0006 \u0003כי הדרן לבתר תריסר ירחי שתא\u0004 \u0005[כאשר חזרנו\u0006 לאותו מקום \u0005לאחר שנים עשר חודשי שנה],\u0006 \u0003חזינהו להנהו גומרי דהוו קא מלחשי\u0004 \u0005[ראינו את הגחלים הללו ש\u0006עדיין \u0005הם לוחשות].\u0006 \u0003כי אתאי לקמיה\u0004 \u0005[כאשר באתי לפני]\u0006 \u0003אמימר, אמר לי: ההוא עישבא\u0004 \u0005[אותו עשב\u0006 ששמתם\u0005]\u0006 \u0003סמתרי הוה\u0004 \u0005[סם חיים היה],\u0006 \u0003הנהו גומרי דריתמא הוו\u0004 \u0005[אותם גחלים של רותם היו].\u0006","ועוד בענין הלויתן נאמר: \u0003\"ויברא אלהים את התנינם הגדלים\"\u0004 (בראשית א, כא), \u0003הכא תרגימו\u0004 \u0005[כאן\u0006 בבבל \u0005תרגמו]:\u0006 \u0003ארזילי דימא\u0004 \u0005[ראמי הים].\u0006 \u0003ר' יוחנן אמר: זה לויתן נחש בריח ולויתן נחש עקלתון, שנאמר: \"ביום ההוא יפקד ה' בחרבו הקשה\u0004 והגדולה והחזקה על לויתן נחש בריח ועל לויתן נחש עקלתון והרג את התנין אשר בים\u0003\"\u0004 (ישעיהו כז, א).","\u0003(סימן\u0004 למימרות הבאות של רבי יהודה בשם רב: \u0003כל\u0004 מה שברא, ב\u0003שעה\u0004 שביקש, \u0003ירדן\u0004 יוצא\u0003). אמר רב יהודה אמר רב: כל מה שברא הקדוש ברוך הוא בעולמו\u0004 — \u0003זכר ונקבה בראם. אף לויתן נחש בריח ולויתן נחש עקלתון\u0004 — \u0003זכר ונקבה בראם. ואלמלי\u0004 (ואם היו) \u0003נזקקין זה לזה\u0004 ומתרבים — היו \u0003מחריבין\u0004 את \u0003כל העולם כולו\u0004 מחמת ריבוי הוולדות; \u0003מה עשה הקדוש ברוך הוא? סירס את הזכר, והרג הנקבה ומלחה\u0004 לסעודה \u0003לצדיקים\u0004 \u0003לעתיד לבא, שנאמר: \"והרג את התנין אשר בים\"\u0004 (ישעיהו כז, א).","\u0003ואף בהמות בהררי אלף\u0004 (ראה תהלים נ, י) — \u0003זכר ונקבה בראם, ואלמלי נזקקין זה לזה\u0004 ומעמידים וולדות — \u0003מחריבין\u0004 היו את \u0003כל העולם כולו\u0004 מרוב גודלם. \u0003מה עשה הקדוש ברוך הוא? סירס\u0004 את \u0003הזכר, וצינן\u0004 את \u0003הנקבה ושמרה לצדיקים לעתיד לבא, שנאמר\u0004 על הבהמות: \u0003\"הנה נא כחו במתניו\"\u0004 (איוב מ, טז) — \u0003זה זכר, \"ואונו בשרירי בטנו\"\u0004 (איוב מ, טז) — \u0003זו נקבה,\u0004 שלא השתמשו באבריהם לשם רביה.","ושואלים: \u0003התם נמי ליסרסיה\u0004 \u0005[שם גם כן,\u0006 בלויתנים, \u0005שיסרס את]\u0006 ה\u0003זכר וליצננה\u0004 \u0005[ויצנן את]\u0006 ה\u0003נקבה!\u0004 ומדוע הרג את הנקבה? ומשיבים: ה\u0003דגים פריצי\u0004 \u0005[פרוצים]\u0006 ואין צינון מועיל להם, ויתרבו בכל זאת. ושואלים: \u0003וליעביד איפכא\u0004 \u0005[ושיעשה להיפך]\u0006 שיהרוג את הזכר וימלחנו! ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003נקבה מליחא מעלי\u0004 \u0005[מלוחה מעולה\u0006 יותר\u0005];\u0006 \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור],\u0006 \u0003כיון דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"לויתן זה יצרת לשחק בו\"\u0004 (תהלים קד, כו), \u0003בהדי\u0004 \u0005[עם]\u0006 ה\u0003נקבה לאו אורח ארעא\u0004 \u0005[אין זה דרך ארץ\u0006 לשחק\u0005].\u0006 ושואלים: \u0003הכא נמי לימלחה\u0004 \u0005[כאן גם כן,\u0006 בבהמות, \u0005שימלח\u0006 את\u0005]\u0006 ה\u0003נקבה,\u0004 ומדוע צינן אותה? ומשיבים: \u0003כוורא מליחא מעלי\u0004 \u0005[דג מלוח טוב\u0006 הוא\u0005],\u0006 \u0003בשרא מליחא לא מעלי\u0004 \u0005[בשר מלוח אינו טוב].\u0006","\u0003ואמר רב יהודה אמר רב: בשעה שביקש הקדוש ברוך הוא לבראות את העולם, אמר לו לשר של ים: פתח פיך ובלע כל מימות שבעולם\u0004 ותיראה היבשה. \u0003אמר לפניו\u0004 השר: \u0003רבונו של עולם, די שאעמוד בשלי\u0004 במים שיש לי בים. \u0003מיד בעט בו\u0004 הקדוש ברוך הוא \u0003והרגו, שנאמר: \"בכחו רגע הים ובתבונתו מחץ רהב\"\u0004 (איוב כו, יב).","\u0003אמר ר' יצחק, שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003שרו של ים \"רהב\" שמו, ואלמלא מים\u0004 שבים \u0003מכסין אותו\u0004 את השר של הים — \u0003אין כל בריה יכולה לעמוד בריחו,\u0004 שהרי מת הוא ומסריח. \u0003שנאמר: \"לא ירעו ולא ישחיתו בכל הר קדשי\u0004 כי מלאה הארץ דעה את ה' \u0003כמים לים מכסים\"\u0004 (ישעיהו יא, ט), \u0003אל תקרי\u0004 (תהא קורא) \u0003\"לים מכסים\", אלא: \"לשרה של ים\u0004 (שהוא הקרוי \"ים\") \u0003מכסים\".\u0004","\u0003ואמר רב יהודה אמר רב:\u0004 נהר ה\u0003ירדן יוצא ממערת פמייס. תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן]:\u0006 \u0003ירדן יוצא ממערת פמייס, ומהלך בימה של סיבכי\u0004 (אגם החולה) \u0003ובימה של טבריא\u0004 (ים כנרת), \u0003ומתגלגל ויורד לים הגדול, ומתגלגל ויורד\u0004 משם \u0003עד ש\u0004הוא \u0003מגיע לפיו של לויתן, שנאמר: \"יבטח כי יגיח ירדן אל פיהו\"\u0004 (איוב מ, כג). \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבא בר עולא: האי\u0004 \u0005[\u0006פסוק \u0005זה]\u0006 \u0003בבהמות בהררי אלף כתיב\u0004 \u0005[נאמר]\u0006 ולא בלויתן! \u0003אלא אמר רבא בר עולא: אימתי בהמות בהררי אלף בטוחות? בזמן שמגיח ירדן בפיו של לויתן.\u0004","\u0003(סימן\u0004 למימרות הבאות של רב דימי: \u0003ימים\u0004 שמקיפים, עתיד \u0003גבריאל,\u0004 בשעה שלויתן \u0003רעב). כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' יוחנן, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"כי הוא על ימים יסדה ועל נהרות יכוננה\"\u0004 (תהלים כד, ב)? — \u0003אלו שבעה ימים וארבעה נהרות שמקיפין את ארץ ישראל, ואלו הן שבעה ימים: ימה של טבריא\u0004 (ים כנרת), \u0003וימה של סדום\u0004 (ים המלח), \u0003וימה של חילת, וימה של חילתא, וימה של סיבכי, וים אספמיא, וים הגדול; ואלו הן ארבעה נהרות: ירדן, וירמוך, וקירומיון ופיגה\u0004 שהם נהרות דמשק.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' יונתן: עתיד\u0004 המלאך \u0003גבריאל לעשות\u0004"],["\u0003קניגיא\u0004 (ציד) \u0003עם לויתן, שנאמר: \"התמשך לויתן בחכה ובחבל תשקיע לשנו\"\u0004 (איוב מ, כה), \u0003ואלמלא הקדוש ברוך הוא עוזרו\u0004 לגבריאל \u0003אין יכול לו, שנאמר: \"העשו יגש חרבו\"\u0004 (איוב מ, יט), כלומר, רק בוראו (\"עושו\") יוכל לסייעו בכך.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' יוחנן: בשעה שלויתן רעב\u0004 הריהו \u0003מוציא הבל מפיו ומרתיח\u0004 כמים המתבשלים בקדירה \u0003כל מימות שבמצולה\u0004 שבתהום הים, \u0003שנאמר: \"ירתיח כסיר מצולה\"\u0004 (איוב מא, כג). \u0003ואלמלא\u0004 היה \u0003מכניס ראשו לגן עדן\u0004 — \u0003אין כל בריה יכולה לעמוד בריחו\u0004 הרע, \u0003שנאמר: \"ים ישים כמרקחה\"\u0004 (איוב מא, כג), ומפרש \"מרקחה\" מלשון מרקחת = בשמים.","\u0003ובשעה שצמא\u0004 — הריהו \u0003עושה תלמים תלמים בים\u0004 כששותה, \u0003שנאמר: \"אחריו יאיר נתיב\"\u0004 (איוב מא, כד). \u0003אמר רב אחא בר יעקב: אין תהום חוזר לאיתנו\u0004 להיות מלא כשהיה לאחר שהלויתן שותה ממנו, \u0003עד\u0004 לאחר \u0003שבעים שנה, שנאמר: \"יחשב תהום לשיבה\"\u0004 (איוב מא, כד), \u0003ואין \"שיבה\" פחותה משבעים\u0004 שנה.","\u0003אמר רבה אמר ר' יוחנן: עתיד הקדוש ברוך הוא לעשות סעודה לצדיקים מבשרו של לויתן, שנאמר: \"יכרו עליו חברים\"\u0004 (איוב מ, ל), \u0003ואין\u0004 משמעות לשון \u0003\"כרה\" אלא סעודה, שנאמר: \"ויכרה להם כרה גדולה ויאכלו וישתו\"\u0004 (מלכים ב ו, כג), \u0003ואין \"חברים\" אלא תלמידי חכמים, שנאמר: \"היושבת בגנים חברים מקשיבים לקולך השמיעני\"\u0004 (שיר השירים ח, יג), שחברים הם תלמידי חכמים המקשיבים לקול ה'.","\u0003והשאר מחלקין אותו ועושין בו סחורה בשוקי ירושלים, שנאמר: \"יחצוהו בין כנענים\"\u0004 (איוב מ, ל), \u0003ואין \"כנענים\" אלא תגרים\u0004 (סוחרים) \u0003שנאמר: \"כנען בידו מאזני מרמה לעשק אהב\"\u0004 (הושע יב, ח). \u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 ראיה \u0003מהכא\u0004 \u0005[מכאן]\u0006 שכנענים הם סוחרים, שנאמר בהקבלה: \u0003\"אשר סחריה שרים, כנעניה נכבדי ארץ\"\u0004 (ישעיהו כג, ח).","\u0003ואמר רבה אמר ר' יוחנן: עתיד הקדוש ברוך הוא לעשות סוכה לצדיקים מעורו של לויתן, שנאמר: \"התמלא בשכות עורו\"\u0004 (איוב מ, לא). אם \u0003זכה\u0004 אדם להגיע לדרגה זו של צדיקים — \u0003עושין לו\u0004 מעור הלויתן \u0003סוכה\u0004 שלימה, \u0003לא זכה\u0004 להגיע לדרגה זו — \u0003עושין לו צלצל,\u0004 כיסוי, צל לראשו, \u0003שנאמר: \"ובצלצל דגים ראשו\"\u0004 (איוב מ, לא).","אם \u0003זכה\u0004 אדם לכך — \u0003עושין לו צלצל, לא זכה\u0004 אף לכך — \u0003עושין לו ענק\u0004 שרשרת (תכשיט לצווארו), \u0003שנאמר: \"וענקים לגרגרתיך\"\u0004 (משלי א, ט). אם \u0003זכה\u0004 לכך — \u0003עושין לו ענק, לא זכה\u0004 אף לזאת — \u0003עושין לו\u0004 מעור הלויתן \u0003קמיע\u0004 בלבד, \u0003שנאמר: \"ותקשרנו לנערותיך\"\u0004 (איוב מ, כט), שעושים לו קשר קטן הקשור על צווארו, כקמיע שתולים לילדים (\"לנערותיך\").","\u0003והשאר\u0004 מעורו של לויתן \u0003פורסו הקדוש ברוך הוא על חומות ירושלים, וזיוו מבהיק מסוף העולם ועד סופו, שנאמר: \"והלכו גוים לאורך ומלכים לנגה זרחך\"\u0004 (ישעיה ס, ג).","אגב הדברים האלה על כבוד ירושלים בעתיד מפרשים את הכתוב: \u0003\"ושמתי כדכד שמשתיך\"\u0004 (ישעיה נד, יב). \u0003אמר ר' שמואל בר נחמני: פליגי\u0004 \u0005[נחלקו]\u0006 בדבר, ממה תיעשנה חומות ירושלים, \u0003תרי מלאכי ברקיעא\u0004 \u0005[שני מלאכים ברקיע]\u0006 והם \u0003גבריאל ומיכאל, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שנחלקו בדבר \u0003תרי אמוראי במערבא\u0004 \u0005[שני אמוראים בארץ ישראל],\u0006 \u0003ומאן אינון\u0004 \u0005[ומי הם]?\u0006 — \u0003יהודה וחזקיה בני ר' חייא, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 מהאבן היקרה הקרויה \u0003שוהם, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 מהאבן היקרה הקרויה \u0003ישפה. אמר להו\u0004 \u0005[להם]\u0006 \u0003הקדוש ברוך הוא: להוי כדין וכדין\u0004 \u0005[שיהא כמו זה וכמו זה]\u0006 גם יחד, וזאת משמעות המלה \"כדכד\" (\"כדין וכדין\").","ומהו פירוש המשך הפסוק \u0003\"ושעריך לאבני אקדח\"\u0004 (ישעיה נד, יב)? \u0003כי הא דיתיב\u0004 \u0005[כמו\u0006 מעשה \u0005זה שישב]\u0006 \u0003ר' יוחנן וקא דריש\u0004 \u0005[והיה דורש]\u0006 כך: \u0003עתיד הקדוש ברוך הוא להביא אבנים טובות ומרגליות שהם\u0004 בגודל \u0003שלשים על שלשים\u0004 אמה, \u0003וחוקק\u0004 (קודח) \u0003בהן\u0004 חור של \u0003עשר על עשרים\u0004 אמה, \u0003ומעמידן בשערי ירושלים. לגלג עליו אותו תלמיד\u0004 שלא נתפרש שמו: \u0003השתא כביעתא דציצלא לא משכחינן\u0004 \u0005[עכשיו\u0006 אבן יקרה \u0005כ\u0006גודל \u0005ביצת התור אין אנו מוצאים],\u0006 \u0003כולי האי משכחינן\u0004 \u0005[כל זה אנו מוצאים]?!\u0006","\u0003לימים\u0004 לאחר זמן \u0003הפליגה ספינתו\u0004 של התלמיד \u0003בים, חזא\u0004 \u0005[ראה]\u0006 \u0003מלאכי השרת דיתבי וקא מינסרי\u0004 \u0005[שיושבים ומנסרים]\u0006 \u0003אבנים טובות ומרגליות שהם\u0004 בגודל \u0003שלשים על שלשים\u0004 אמה \u0003וחקוק בהן עשר ברום עשרים, אמר להו\u0004 \u0005[להם]\u0006 למלאכים: \u0003הני למאן\u0004 \u0005[אלה למי]?\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003שעתיד הקדוש ברוך הוא להעמידן בשערי ירושלים. אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003ר' יוחנן\u0004 לאחר מעשה, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003דרוש, רבי, לך נאה לדרוש, כאשר אמרת כן ראיתי. אמר לו\u0004 ר' יוחנן: \u0003ריקא! אלמלא לא ראית לא האמנת,\u0004 אם כן \u0003מלגלג על דברי חכמים אתה, נתן עיניו בו ונעשה גל של עצמות,\u0004 שמת מיד.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דברי ר' יוחנן: נאמר \u0003\"ואולך אתכם קוממיות\"\u0004 (ויקרא כו, יג) — \u0003ר' מאיר אומר:\u0004 עתידים ישראל להיות בגודל של \u0003מאתים אמה,\u0004 שהם \u0003כשתי קומות\u0004 (\"קוממיות\") \u0003של אדם הראשון\u0004 שהיה גובהו מאה אמה.","\u0003ר' יהודה אומר:\u0004 יגיעו לגובה \u0003מאה אמה, כנגד היכל וכתליו, שנאמר: \"אשר בנינו כנטעים מגדלים בנעוריהם, בנותינו כזוית מחטבות תבנית היכל\"\u0004 (תהלים קמד, יב), שאף בנות ישראל יגיעו להיות גבוהות כתבנית היכל, שבבית שני היה גובהו מאה אמה. ואם גודל הפתח שבשערי ירושלים יהיה עשר על עשרים אמה, כדברי ר' יוחנן, כיצד עתידים בני ישראל להיכנס בשערים אלה שיהיו קטנים עבורם? ומשיבים: \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003ר' יוחנן\u0004 לא לשערים עצמם התכוון אלא \u0003לכווי דבי זיקא\u0004 \u0005[לחלונות\u0006 שישמשו לכניסת \u0005הרוח].\u0006","\u0003ואמר רבה אמר ר' יוחנן: עתיד הקדוש ברוך הוא לעשות שבע חופות לכל צדיק וצדיק, שנאמר: \"וברא ה' על כל מכון הר ציון ועל מקראה ענן יומם ועשן ונגה אש להבה לילה כי על כל כבוד חפה\"\u0004 (ישעיה ד, ה), וכאשר מונים את הדברים שנאמרו בפסוק זה: ענן, עשן, נוגה וכו' הרי שבע. \u0003מלמד שכל אחד ואחד עושה לו הקדוש ברוך הוא חופה\u0004 כפולת שבע \u0003לפי כבודו,\u0004 שלפי מעלתו מייפים ומגדילים את חופתו.","ושואלים: \u0003עשן בחופה למה? אמר ר' חנינא: שכל מי שעיניו צרות בתלמידי חכמים בעולם הזה, מתמלאות עיניו עשן לעולם הבא\u0004 מחופה זו. ושואלים: \u0003ואש בחופה למה? אמר ר' חנינא: מלמד שכל אחד ואחד נכוה מחופתו של חבירו,\u0004 שהוא מסתכל בה ומתבייש מגודל החופה של חבירו, ואומר: \u0003אוי לה לאותה בושה, אוי לה לאותה כלימה\u0004 שלא זכיתי לכך.","\u0003כיוצא בדבר אתה אומר:\u0004 נאמר למשה על יהושע \u0003\"ונתתה מהודך עליו\"\u0004 (במדבר כז, כ) ומדייקים \"מהודך\" \u0003ולא כל הודך, זקנים שבאותו הדור אמרו: פני משה\u0004 היו מאירים \u0003כפני חמה, פני יהושע כפני לבנה, אוי לה לאותה בושה, אוי לה לאותה כלימה\u0004 שלא זכינו שיהיה מנהיגנו באותה מדרגה.","\u0003אמר ר' חמא בר חנינא: עשר חופות עשה הקדוש ברוך הוא לאדם הראשון בגן עדן, שנאמר\u0004 לחירם מלך צור: \u0003\"בעדן גן אלהים היית כל אבן יקרה\u0004 מסכת \u0003ך\u0004 אודם פטדה ויהלום תרשיש שוהם וישפה ספיר נופך וברקת וזהב, מלאכת תופיך ונקביך בך ביום הבראך כוננו\u0003\"\u0004 (יחזקאל כח, יג), הרי עשרה דברים, מאודם עד זהב. \u0003מר זוטרא אמר: אחת עשרה\u0004 חופות היו, \u0003שנאמר: \"כל אבן יקרה\"\u0004 (יחזקאל כח, יג) והיא נמנית לעצמה. \u0003אמר ר' יוחנן: וגרוע שבכולן זהב, דקא חשיב ליה\u0004 \u0005[שמונה אותו]\u0006 \u0003לבסוף,\u0004 משמע ששאר הדברים היו יקרים יותר.","אגב הזכרת כתוב זה שואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מלאכת תפיך ונקביך בך\"\u0004 (יחזקאל כח, יג)? \u0003אמר רב יהודה אמר רב: אמר לו הקדוש ברוך הוא לחירם מלך צור\u0004 שנאמר בו שעשה לעצמו כל אלה: וכי בגן עדן היית שעשית לך כל אלו? \u0003בך נסתכלתי\u0004 שאתה עשית את עצמך לאלוה, \u0003ובראתי נקבים נקבים באדם\u0004 של צואה ומי רגלים, שתדע שאתה בשר ודם, ולא אל. \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים],\u0006 \u0003הכי קאמר\u0004 \u0005[כך אמר]\u0006 לו: \u0003בך נסתכלתי,\u0004"],["\u0003וקנסתי מיתה על אדם הראשון\u0004 שכיון שמת יודעים שאדם הוא ולא אל.","ושבים לפסוק שנזכר קודם \"וברא ה' על כל מכון הר ציון ועל מקראיה ענן יומם\" וכו' (ישעיה ד, ה), ומבררים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"ועל מקראה\"?\u0004 \u0003אמר רבה אמר ר' יוחנן: לא כירושלים של עולם הזה ירושלים של עולם הבא; ירושלים של עולם הזה\u0004 — \u0003כל הרוצה לעלות\u0004 אליה \u0003עולה, של עולם הבא\u0004 — \u0003אין עולין אלא המזומנין\u0004 (=קרואים) \u0003לה.\u0004","\u0003ואמר רבה אמר ר' יוחנן: עתידין צדיקים שנקראין על שמו של הקדוש ברוך הוא, שנאמר: \"כל הנקרא בשמי ולכבודי בראתיו יצרתיו אף עשיתיו\"\u0004 (ישעיה מג, ז), הרי שמי שנברא וגורם לכבודו של הקדוש ברוך הוא נקרא בשמו. \u0003ואמר ר' שמואל בר נחמני אמר ר' יוחנן: שלשה נקראו על שמו של הקדוש ברוך הוא, ואלו הן: צדיקים, ומשיח, וירושלים.\u0004","ומפרט: \u0003צדיקים\u0004 — \u0003הא דאמרן\u0004 \u0005[זו שאמרנו]\u0006 קודם. \u0003משיח\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 במשיח: \u0003\"וזה שמו אשר יקראו ה' צדקנו\"\u0004 (ירמיהו כג, ו), הרי שהוא נקרא על שמו של ה'. \u0003ירושלים\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בה בסוף ספר יחזקאל: \u0003\"סביב שמנה עשר אלף ושם העיר מיום ה' שמה\"\u0004 (מח, לה), \u0003אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003\"שמה\" אלא \"שמה\"\u0004 שהעיר תיקרא בשמו של ה'. ובענין זה \u0003אמר ר' אלעזר: עתידין צדיקים שאומרים לפניהן \"קדוש\", כדרך שאומרים לפני הקדוש ברוך הוא, שנאמר: \"והיה הנשאר בציון והנותר בירושל ם קדוש יאמר לו\"\u0004 (ישעיהו ד, ג).","\u0003ואמר רבה אמר ר' יוחנן: עתיד הקדוש ברוך הוא להגביה את ירושלים שלש פרסאות למעלה, שנאמר: \"וראמה וישבה תחתיה\"\u0004 (זכריה יד, י), \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"תחתיה\"?\u0004 — \u0003כתחתיה,\u0004 שרומה יהא כתחתיה. ושואלים לבירור הענין: \u0003וממאי דהאי\u0004 \u0005[שזה]\u0006 \u0003\"תחתיה\"\u0004 של ירושלים \u0003תלתא פרסי הויא\u0004 \u0005[שלוש פרסות הן]?\u0006 \u0003אמר רבה, אמר לי ההוא סבא\u0004 \u0005[זקן אחד]:\u0006 \u0003לדידי חזי לי\u0004 \u0005[אני ראיתי]\u0006 את \u0003ירושלים קמייתא\u0004 \u0005[הראשונה]\u0006 כשהיתה בבניינה, \u0003ותלתא פרסי הויא\u0004 \u0005[ושלוש פרסות היתה].\u0006","וממשיכים בדברי ר' יוחנן, \u0003ושמא תאמר: יש צער לעלות\u0004 למקום גבוה כל כך? — \u0003תלמוד לומר\u0004 בנבואה המתארת חזרתם של ישראל לירושלים: \u0003\"מי אלה כעב תעופינה וכיונים אל ארבתיהם\"\u0004 (ישעיהו ס, ח), כלומר, שיוכלו להגיע לשם בקלות, כמו היו עננים או יונים. \u0003אמר רב פפא: שמע מינה\u0004 \u0005[למד מכאן]\u0006 בדרך אגב ש\u0003האי עיבא\u0004 \u0005[ענן זה]\u0006 — \u0003תלתא פרסי מידלי\u0004 \u0005[שלוש פרסות\u0006 הוא \u0005גבוה],\u0006 שהרי גובהה של ירושלים אליה מגיע הענן הוא שלוש פרסאות.","\u0003אמר ר' חנינא בר פפא: בקש הקדוש ברוך הוא לתת את ירושלים במדה\u0004 קבועה, \u0003שנאמר\u0004 בחזונו של זכריה: \u0003\"\u0004ואשא עיני וארא והנה איש ובידו חבל מידה. \u0003ואמר אנה אתה הלך ויאמר אלי למד את ירושל ם לראות כמה רחבה וכמה ארכה\"\u0004 (זכריה ב, ה–ו), באותה שעה","\u0003אמרו מלאכי השרת לפני הקדוש ברוך הוא: רבונו של עולם, הרבה כרכים בראת בעולמך של אומות העולם\u0004 — \u0003ולא נתת מדת ארכן ומדת רחבן\u0004 להגבילן, והן גדלות לפי התפתחותן, ואילו \u0003ירושלים ששמך בתוכה ומקדשך בתוכה וצדיקים בתוכה\u0004 — \u0003אתה נותן בה מדה? מיד: \"ויאמר אלו רץ דבר אל הנער הלז לאמר פרזות תשב ירושל ם מרב אדם ובהמה בתוכה\"\u0004 (זכריה ב, ח).","ובענין זה \u0003אמר ריש לקיש: עתיד הקדוש ברוך הוא להוסיף על ירושל ם אלף טפף גינואות\u0004 (גינות), \u0003אלף קפל מגדלים, אלף ליצוי בירניות\u0004 (ביצורים ), \u0003אלף ושני שילה טוטפראות\u0004 (בתים קטנים), \u0003וכל אחת ואחת\u0004 מהתוספות הללו \u0003הויא\u0004 \u0005[תהיה]\u0006 \u0003כ\u0004מו העיר הגדולה \u0003צפורי\u0004 בתקופתה הטובה, בהיותה \u0003בשלוותה.\u0004","ומספרים כמה גדולה היתה אז העיר ציפורי: \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' יוסי: אני ראיתי\u0004 את העיר \u0003צפורי\u0004 בהיותה \u0003בשלוותה, והיו בה מאה ושמונים אלף שווקים של מוכרי ציקי קדירה\u0004 (רטבים לתבשיל), ומכאן אפשר לשער מה יהיה גודלה של ירושלים לעתיד לבוא.","וכיוצא בזה דרשו את הפסוק \u0003\"והצלעות צלע אל צלע שלוש ושלשים פעמים\"\u0004 (יחזקאל מא, ו) — \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"שלוש ושלשים פעמים\"? אמר ר' לוי, אמר רב פפי משום\u0004 (בשם) \u0003ר' יהושע דסכני: אם שלש ירושלים הן,\u0004 אם תגדל העיר פי שלוש בשטחה מזה שהיה בעבר בזמן בניינה — \u0003כל אחת ואחת יש בה שלשים מדורין\u0004 (קומות) \u0003למעלה\u0004 בכל בית, \u0003אם שלשים ירושלים הן\u0004 — \u0003כל אחת ואחת יש בה שלשה מדורין למעלה.\u0004","לאחר שעסקנו בענייני אגדה חוזרים לצד ההלכה של משנתנו, לדון עוד בקניית ספינה. \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים ביחס לאופן קניית \u0003ספינה\u0004 — \u0003רב אמר: כיון שמשך כל שהוא\u0004 והזיז אותה ממקומה אפילו במשהו — \u0003קנה\u0004 אותה בכך. \u0003ושמואל אמר: לא קנה עד שימשוך את כולה,\u0004 שיזיזנה עד שתהלך כדי כל אורכה ותצא לגמרי מהמקום בו היתה קודם.","ומציעים: \u0003לימא כתנאי\u0004 \u0005[האם לומר\u0006 שמחלוקת זו היא \u0005כ\u0006מחלוקת \u0005תנאים],\u0006 ששנינו בברייתא: \u0003כיצד\u0004 בהמה נקנית \u0003במסירה?\u0004 אם \u0003אחזה בטלפה\u0004 (פרסתה), או \u0003בשערה,\u0004 או \u0003באוכף שעליה,\u0004 או \u0003בשליף\u0004 (משא) \u0003שעליה,\u0004 או \u0003בפרומביא\u0004 (רסן) \u0003שבפיה,\u0004 או \u0003בזוג\u0004 (בפעמון) \u0003שבצוארה\u0004 — \u0003קנאה. כיצד\u0004 בהמה נקנית \u0003במשיכה? קורא לה והיא באה\u0004 אליו, \u0003או שהכישה\u0004 (היכה אותה) \u0003במקל ורצתה\u0004 (ורצה) \u0003לפניו, כיון שעקרה יד ורגל\u0004 ממקומה — \u0003קנאה. ר' אחי, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 \u0003ר' אחא אומר:\u0004 לא די שתעקור יד או רגל, אלא \u0003עד שתהלך מלא קומתה.\u0004","ואם כן \u0003לימא\u0004 \u0005[האם נאמר]\u0006 ש\u0003רב\u0004 שאמר באופן קניית ספינה שדי שימשוך כלשהו, \u0003אמר כ\u0004שיטת \u0003ה\u0004\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 שדי בעקירת יד או רגל, \u0003ושמואל\u0004 שאמר בספינה שאינה נקנית אלא במשיכת כולה \u0003אמר כ\u0004שיטת \u0003ר' אחא\u0004 שצריך שתיעקר הבהמה כולה ממקומה! ודוחים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רב: אנא דאמרי\u0004 \u0005[אני שאמרתי]\u0006 \u0003אפילו ל\u0004דעת \u0003ר' אחא\u0004 אמרתי, ש\u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' אחא\u0004 הלכה זו — \u0003אלא בבעלי חיים, דאף על גב\u0004 \u0005[שאף על פי]\u0006 \u0003דעקרה\u0004 \u0005[שעוקרת]\u0006 \u0003יד ורגל\u0004 — \u0003בדוכתה קיימא\u0004 \u0005[במקומה\u0006 היא \u0005עומדת],\u0006 \u0003אבל ספינה, כיון דנדה\u0004 \u0005[שנעה]\u0006 \u0003בה פורתא\u0004 \u0005[מקצת]\u0006 \u0003נדה\u0004 \u0005[נעה]\u0006 \u0003לה כולה\u0004 וקונה בכך.","\u0003ושמואל אמר: אנא דאמרי\u0004 \u0005[אני שאמרתי]\u0006 \u0003אפילו כ\u0004שיטת ה\u0003תנא קמא\u0004 \u0005[הראשון],\u0006 שכן \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 — \u0003אלא בבעלי חיים,\u0004 ש\u0003כיון דמיעקרא\u0004 \u0005[שנעקרת]\u0006 \u0003יד ורגל\u0004 — \u0003אידך למיעקר קיימא\u0004 \u0005[שאר\u0006 הגוף גם כן \u0005להיעקר\u0006 ממקומו הוא \u0005עומד],\u0006 \u0003אבל ספינה, אי משיך לה\u0004 \u0005[אם מושך אותה]\u0006 \u0003כולה —\u0004 \u0003אין\u0004 \u0005[כן]\u0006 נקנית, \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא\u0004 — \u0003לא.\u0004","ומציעים עוד: \u0003לימא כהני תנאי\u0004 \u0005[האם לומר\u0006 שמחלוקת רב ושמואל בספינה \u0005כ\u0006מחלוקת \u0005תנאים אלה]\u0006 היא\u0005,\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ספינה נקנית במשיכה, ר' נתן אומר: ספינה ואותיות\u0004 כגון שטר חוב שקונה מחבירו וקונה את החוב שבו, \u0003נקנות במשיכה\u0004"],["\u0003ובשטר.\u0004","ותחילה מבררים את הברייתא: \u0003אותיות מאן דכר שמייהו\u0004 \u0005[מי הזכיר\u0006 כלל את \u0005שמן]?\u0006 מדוע בא ר' נתן לדבר על אותיות כשלא דובר בהן קודם, בדברי התנא הראשון? ומשיבים: \u0003חסורי מחסרא והכי קתני\u0004 \u0005[חסרה\u0006 הברייתא \u0005וכך היא שנויה]:\u0006 \u0003ספינה נקנית במשיכה, ואותיות במסירה\u0004 בלבד, בלא למשוך את השטר. \u0003ר' נתן אומר: ספינה ואותיות נקנות במשיכה ובשטר.\u0004","ושואלים: \u0003שטר לספינה למה לי?\u0004 הלא \u0003מטלטלי\u0004 \u0005[מיטלטלים]\u0006 \u0003היא,\u0004 ומיטלטלים אינם נקנים בשטר אלא באופנים אחרים! \u0003אלא לאו הכי קתני\u0004 \u0005[האם לא כך\u0006 היא \u0005שנויה]:\u0006 \u0003ספינה נקנית במשיכה, ואותיות במסירה. ר' נתן אומר: ספינה במשיכה, ואותיות\u0004 גם במסירה וגם \u0003בשטר.\u0004","ויש לשאול: אם כך ר' נתן האומר ש\u0003ספינה במשיכה היינו\u0004 \u0005[זה]\u0006 כדעת ה\u0003תנא קמא\u0004 \u0005[הראשון],\u0006 \u0003אלא\u0004 האם לא מחלוקת זו של \u0003רב ושמואל איכא בינייהו\u0004 \u0005[יש ביניהם],\u0006 שאחד מהם סבור שצריכים משיכה משהו בספינה, והאחר סבור כי צריך משיכה של כולה? ודוחים: \u0003לא, דכולי עלמא\u0004 \u0005[לדעת הכל,\u0006 תנא קמא ור' נתן\u0005]\u0006 אפשר לומר שהם סבורים \u0003אי\u0004 \u0005[או]\u0006 \u0003כרב אי\u0004 \u0005[או]\u0006 \u0003כשמואל, ובספינה\u0004 — \u0003כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חולקים]\u0006 שנקנית במשיכה,","\u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה \u0003ב\u0004מכירת \u0003אותיות\u0004 (שטרות), \u0003והכי קאמר ליה\u0004 \u0005[וכך אמר לו]\u0006 \u0003ר' נתן לתנא קמא\u0004 \u0005[הראשון]:\u0006 \u0003בספינה ודאי מודינא\u0004 \u0005[מודה אני]\u0006 \u0003לך\u0004 שנקנית במשיכה. \u0003באותיות,\u0004 שאתה סבור שדי במסירה, לדעתי \u0003אי איכא\u0004 \u0005[אם יש]\u0006 גם \u0003שטר\u0004 מכירה — \u0003אין\u0004 \u0005[כן],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא\u0004 — \u0003לא. ו\u0004לפי זה חולקים תנא קמא ור' נתן","\u0003בפלוגתא דהני תנאי\u0004 \u0005[במחלוקת של תנאים אלה];\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אותיות נקנות במסירה,\u0004 אלו \u0003דברי רבי. וחכמים אומרים: בין כתב\u0004 שטר מכירה על השטר \u0003ולא מסר, בין מסר ולא כתב\u0004 — \u0003לא קנה עד שיכתוב וימסור.\u0004","שואלים: לדרך זו \u0003במאי אוקימתא\u0004 \u0005[במה העמדת\u0006 אותה\u0005]\u0006 את שיטת תנא קמא בברייתא הקודמת, \u0003כ\u0004שיטת \u0003רבי?\u0004 הרי לשיטתו \u0003ספינה נמי תיקני\u0004 \u0005[גם כן תיקנה]\u0006 \u0003במסירה,\u0004 ולאו דווקא במשיכה (כפי שנאמר באותה ברייתא). ומנין שכן דעת רבי? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ספינה נקנית במסירה,\u0004 אלו \u0003דברי רבי. וחכמים אומרים: לא קנה\u0004"],["\u0003עד שימשכנה או עד שישכור את מקומה,\u0004 ואם כן, איך אפשר לייחס את דעת תנא קמא לרבי?","ודוחים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003כאן\u0004 שאמר רבי שספינה נקנית במסירה, מדובר כשהיתה הספינה עומדת \u0003ברשות הרבים\u0004 שאינה נקנית שם במשיכה, ולכן היא נקנית במסירה, \u0003כאן\u0004 מדובר \u0003בסימטא,\u0004 מבוי קטן, שאינו רשות הרבים, ושניהם רשאים להניח חפציהם בו, ובמקום כזה צריך לקנות במשיכה.","ושואלים: \u0003במאי אוקימתא להא בתרייתא\u0004 \u0005[במה העמדת את זו\u0006 הברייתא \u0005האחרונה]?\u0006 — \u0003ברשות הרבים; אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה],\u0006 \u0003וחכמים אומרים: לא קנה עד שימשכנה\u0004 או עד שישכור את מקומה. \u0003ואי\u0004 \u0005[ואם]\u0006 מדובר \u0003ברשות הרבים, ממאן אוגיר\u0004 \u0005[ממי ישכור]\u0006 את המקום? \u0003ותו\u0004 \u0005[ועוד],\u0006 \u0003משיכה ברשות הרבים מי קניא\u0004 \u0005[האם\u0006 היא \u0005קונה]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אביי ורבא דאמרי תרוייהו\u0004 \u0005[שאומרים שניהם]\u0006 באופני הקניינים השונים: \u0003מסירה קונה ברשות הרבים ובחצר שאינה של שניהם, משיכה קונה בסימטא ובחצר שהיא של שניהם\u0004 יחד, \u0003והגבהה קונה בכל מקום,\u0004 וגם ברשות המוכר. ולענייננו — משיכה אינה קונה ברשות הרבים!","ומתרצים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"עד שימשכנה\" נמי דקאמר\u0004 \u0005[גם כן שהוא אומר],\u0006 \u0003ו\u0004כן \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"עד שישכור את מקומה\" דקאמר\u0004 \u0005[שהוא אומר]?\u0006 \u0003הכי קאמר\u0004 \u0005[הוא אומר]\u0006 כך היתה הכוונה: \u0003עד שימשכנה מרשות הרבים לסימטא, ואם רשות\u0004 ה\u0003בעלים היא\u0004 שהיתה הספינה עומדת במקום שיש לו בעלים — \u0003לא קנה עד שישכור את מקומה\u0004 מן הבעלים.","ושואלים: האם \u0003לימא\u0004 \u0005[לומר]\u0006 ש\u0003אביי ורבא דאמרי\u0004 \u0005[שאומרים]\u0006 \u0003כ\u0004דעת \u0003רבי\u0004 ולא כדעת חכמים? שהרי מן הברייתא עולה שרק לדעת רבי ניתן לקנות במסירה ברשות הרבים!","\u0003אמר רב אשי:\u0004 באמת אף חכמים מודים שברשות הרבים קונה במסירה, ולכן \u0003אי דאמר ליה\u0004 \u0005[אם שאומר לו]\u0006 \u0003\"לך חזק וקני\u0004 \u0005[החזק וקנה]\u0006 \u0003\"\u0004— \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 שדי לו בקנין מסירה, ואינו צריך למשוך. \u0003הכא\u0004 \u0005[כאן]\u0006 שחכמים חלקו על רבי \u0003במאי עסקינן\u0004 \u0005[במה אנו עוסקים]\u0006 — במקרה מיוחד, \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 \u0003\"לך משוך וקני\"\u0004 \u0005[וקנה],\u0006","\u0003מר סבר\u0004 \u0005[חכם זה,\u0006 חכמים, \u0005סבור]:\u0006 \u0003קפידא\u0004 \u0005[הקפדה]\u0006 יש בכך שהמוכר עומד על כך שיקננה רק בדרך זו, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 רבי \u0005סבור]:\u0006 \u0003מראה מקום הוא לו,\u0004 שאינו מקפיד שיהא הקנין במשיכה דווקא, אלא הזכיר דרך זו, אבל בכל דרך חוקית של קנין יכול לקנות.","ושבים לדון בענין קנין אותיות. \u0003אמר רב פפא: האי מאן דמזבין ליה שטרא לחבריה\u0004 \u0005[מי שמוכר לו שטר לחבירו],\u0006 \u0003צריך למיכתב ליה\u0004 \u0005[לכתוב לו]:\u0006 \u0003\"קני הוא וכל שעבודא דביה\"\u0004 \u0005[קנה אותו וכל שיעבוד שבתוכו].\u0006 \u0003אמר רב אשי: אמריתה לשמעתא קמיה\u0004 \u0005[אמרתי את ההלכה\u0006 הזו \u0005לפני]\u0006 \u0003רב כהנא, ואמרית ליה\u0004 \u0005[ואמרתי לו]\u0006 והקשיתי עליה כך: מתוך הדברים יש לדייק, כי \u0003טעמא דכתב ליה הכי\u0004 \u0005[\u0006\u0005הטעם,\u0006 דווקא \u0005שכותב לו כך]\u0006 הוא שקונה הלה את השטר והשיעבוד שבו, \u0003הא לא כתב ליה הכי\u0004 \u0005[הרי\u0006 אם \u0005אינו כותב לו כך]\u0006 — \u0003לא קני\u0004 \u0005[אינו קונה]\u0006 את השיעבוד שבשטר, ואולם אם כן הוא — לשם מה קנה את השטר?","\u0003וכי לצור על פי צלוחיתו הוא צריך?\u0004 האם תאמר שקנה אותו בשביל הנייר בלבד, להשתמש בו לכיסוי צלוחית?! \u0003אמר לי: אין\u0004 \u0005[כן],\u0006 \u0003לצור ולצור,\u0004 ואם לא הקנה במפורש את השיעבוד לא חל הקנין אלא על הנייר של השטר."],["\u0003אמר אמימר, הלכתא\u0004 \u0005[\u0006פסק \u0005הלכה\u0006 הוא\u0005]:\u0006 \u0003אותיות\u0004 השטר, ההתחייבות הכתובה בו — \u0003נקנות במסירה\u0004 של השטר לידי הקונה, \u0003כ\u0004דברי \u0003רבי. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לאמימר:\u0004 האם מן ה\u0003גמרא\u0004 \u0005[מסורת]\u0006 אתה פוסק כך, \u0003או\u0004 שמא מן ה\u0003סברא?\u0004 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003גמרא\u0004 \u0005[מסורת\u0006 היא\u0005].\u0006 \u0003אמר רב אשי: סברא נמי הוא\u0004 \u0005[גם כן היא]\u0006 שהשטרות נקנים במסירה, ש\u0003אותיות,\u0004 כלומר, השטרות, הרי \u0003מילי נינהו\u0004 \u0005[דברים הם],\u0006 שהרי אינו קונה דבר של ממש, אלא התחייבות, \u0003ומילי במילי לא מיקנין\u0004 \u0005[ודברים בדברים אינם נקנים].\u0006","ותוהים: \u0003ולא\u0004 (האם אין זה כך) שקונים שטר בדברים? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבה בר יצחק אמר רב, שני\u0004 סוגי \u0003שטרות הם:\u0004 האחד — אם אומר לעדים \u0003\"זכו בשדה לפלוני וכתבו לו את השטר\u0004 על כך \u0003\"\u0004— \u0003חוזר בשטר,\u0004 שיכול לומר לעדים שאינו רוצה שייכתב שטר, \u0003ואינו חוזר ב\u0004נתינת ה\u0003שדה,\u0004 שהרי כבר זכו בו למקבל.","השטר השני — אם אמר \u0003\"\u0004זכו בשדה לפלוני \u0003על מנת שתכתבו לו את השטר\"\u0004 כל עוד לא כתבו את השטר — \u0003חוזר בין בשטר בין בשדה,\u0004 שהרי הזכייה בשדה הותנתה מראש בכתיבת השטר, ואם חזר בו מן השטר, חזר בו מן הכל.","\u0003ורב חייא בר אבין אמר\u0004 בשם \u0003רב הונא, שלשה שטרות הן: תרי\u0004 \u0005[שנים]\u0006 — \u0003הא דאמרן\u0004 \u0005[אלה שאמרנו];\u0006 \u0003אידך\u0004 \u0005[האחר]:\u0006 \u0003אם קדם מוכר וכתב את השטר\u0004 לפני שהקונה שילם."],["\u0003כאותה ששנינו: כותבין שטר למוכר אף על פי שאין\u0004 ה\u0003לוקח עמו,\u0004 שאנו מניחים שכיון שהשטר ביד המוכר הוא ישתדל שלא תבוא לו מכאן תקלה. ובאופן כזה של שטר, \u0003כיון שהחזיק זה\u0004 הקונה \u0003בקרקע\u0004 — \u0003נקנה\u0004 לו \u0003שטר\u0004 זה \u0003בכל מקום שהוא, ו\u0004אפשרות \u0003זו היא ששנינו\u0004 במשנה אחרת: \u0003נכסים שאין להן אחריות\u0004 (כגון מיטלטלים מכל סוג) \u0003נקנין\u0004 יחד \u0003עם נכסים שיש להן אחריות\u0004 (מקרקעין), כאשר אלה נקנים \u0003בכסף ושטר וחזקה.\u0004 ואנו רואים איפוא, כי אף שקניין אגב אינו אלא מילים, מכל מקום קונה על ידו שטר, ושלא כדברי רב אשי, הסבור שאין שטר נקנה בדברים בלבד!","ואומרים: מכאן אין ראיה, כי קנין \u0003אגב שאני\u0004 \u0005[שונה],\u0006 והוא נחשב כדין קנין של ממש, שלא כדברים בלבד. וראיה לתוקפו של קנין זה \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003מטבע\u0004 ש\u0003לא ניקני\u0004 \u0005[נקנה]\u0006 \u0003בחליפין, ואגב ארעא ניקני\u0004 \u0005[ועל גב קרקע\u0006 הוא \u0005נקנה].\u0006","\u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 ש\u0003רב פפא הוו ליה תריסר אלפי זוזי בי\u0004 \u0005[היו לו שנים עשר אלף זוזים בבית]\u0006 \u0003חוזאי, אקנינהו ניהליה\u0004 \u0005[הקנה אותם לו]\u0006 \u0003לרב שמואל בר אחא אגב אסיפא דביתיה\u0004 \u0005[על גב סף ביתו],\u0006 שהקנה לו את סף ביתו, ואגב כך הקנה לו את הכסף, שהיה בבית חוזאי. ומספרים \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 רב שמואל בר אחא משם עם הכסף \u0003נפק\u0004 \u0005[יצא]\u0006 רב פפא \u0003לאפיה\u0004 \u0005[לקראתו]\u0006 \u0003עד\u0004 המקום \u0003תווך,\u0004 ששמח כל כך שהכסף הגיע אליו.","שנינו במשנה שהמוכר את הספינה מכר דברים שונים שבה \u0003אבל לא מכר לא את העבדים ולא את המרצופין ולא את האנתיקי וכו'.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אנתיקי\"? אמר רב פפא: עיסקא דבגווה\u0004 \u0005[העסק,\u0006 הסחורה, \u0005ש\u0006נמצאת \u0005בתוכה]\u0006 שאינה נמכרת עם הספינה.","\u0003מכר את הקרון\u0004 — \u0003לא מכר\u0004 עמו \u0003את הפרדות\u0004 המושכות אותו. וכן מן הצד האחר אם \u0003מכר את הפרדות\u0004 — \u0003לא מכר\u0004 עימן \u0003את הקרון. מכר את הצמד,\u0004 עול הקושר ומצמיד שתי בהמות זו לזו לצורך חרישה או משא — \u0003לא מכר את הבקר.\u0004 וכן אם \u0003מכר את הבקר\u0004 — \u0003לא מכר את הצמד. ר' יהודה אומר: הדמים מודיעין\u0004 (מלמדים) מה מכר, \u0003כיצד?\u0004 אם \u0003אמר לו: מכור לי צימדך במאתים זוז, הדבר ידוע שאין הצמד,\u0004 כלומר, גוף העול עצמו, נמכר ב\u0003מאתים זוז,\u0004 אלא ודאי התכוון לקנות את הבקר עם העול שעליו, \u0003וחכמים אומרים: אין הדמים ראיה.\u0004","בהלכה זו של מכירת קרון \u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב תחליפא בר מערבא\u0004 \u0005[בן ארץ ישראל]\u0006 \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' אבהו\u0004 ברייתא זו: \u0003מכר את הקרון\u0004 — \u0003מכר את הפרדות.\u0004 והתקשה ר' אבהו: \u0003והא אנן\u0004 \u0005[והרי אנו]\u0006 \u0003\"לא מכר\" תנן\u0004 \u0005[שנינו]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב תחליפא לר' אבהו: אם כן, \u0003איסמייה\u0004 \u0005[אמחוק אותה]\u0006 את הברייתא הזו, שאינה נכונה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא,\u0004 אל תמחק, \u0003תיתרגם מתניתיך\u0004 \u0005[תרגם,\u0006 הסבר \u0005את\u0006 \u0005הברייתא שלך]\u0006 \u0003ב\u0004מקרה שהיו הפרדות \u0003אדוקין\u0004 (קשורים) \u0003בו\u0004 בקרון, ואז ההנחה היא שכשקונה את הקרון הפרדות נמכרות יחד איתו.","שנינו במשנה: \u0003מכר את הצמד\u0004 — \u0003לא מכר את הבקר וכו',\u0004 שנחלקו חכמים ור' יהודה האם הדמים מודיעים. ומבררים את מחלוקתם: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אילימא דקרו לצימדא \"צימדא\"\u0004 \u0005[אם תאמר\u0006 במקום \u0005שקוראים לצמד \"צמד\"],\u0006 \u0003ולבקר \"בקר\",\u0004 אם כן \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר, כי \u0003צימדא זבין ליה\u0004 \u0005[צמד מכר לו],\u0006 \u0003בקר לא זבין ליה\u0004 \u0005[מכר לו]!\u0006 \u0003ואלא\u0004 תאמר שמדובר במקום \u0003דקרו ליה נמי\u0004 \u0005[שקוראים לו גם כן]\u0006 \u0003לבקר \"צימדא\"\u0004 \u0005[צמד],\u0006 אם כן \u0003כוליה זבין ליה\u0004 \u0005[\u0006את \u0005הכל,\u0006 גם את הבקר, \u0005מכר לו]\u0006 שהרי הסכום שנקבע מורה למה הכוונה!","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה],\u0006 אלא \u0003באתרא דקרו ליה לצימדא \"צימדא\"\u0004 \u0005[במקום שקוראים לו לצמד \"צמד\"],\u0006 \u0003ולבקר \"בקר\", ואיכא נמי דקרו\u0004 \u0005[ויש גם כן\u0006 כאלה \u0005שקוראים]\u0006 \u0003לבקר\u0004 \u0003\"צימדא\"\u0004 \u0005[\"צמד\"],\u0006 \u0003ר' יהודה סבר\u0004 \u0005[סבור]\u0006 שבמקרה כזה, שאין בהירות בלשון, \u0003הדמים מודיעין\u0004 אם קנה צמד או בקר. \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]\u0006 ש\u0003אין הדמים ראיה.\u0004 ושואלים: \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003אין הדמים ראיה,\u0004 והוא נותן מאתיים זוז ומקבל רק צמד של עץ או ברזל, \u0003ליהוי\u0004 \u0005[יהא זה]\u0006 \u0003ביטול מקח,\u0004 שהרי ודאי אין הצמד שווה סכום זה, אלא פי כמה וכמה מהמחיר שלו, ובמקרה של הונאה יותר משישית — מתבטל המיקח לגמרי!"],["\u0003וכי תימא\u0004 \u0005[ואם תאמר],\u0006 \u0003ביטול מקח לרבנן לית להו\u0004 \u0005[לחכמים אין להם]\u0006 במקרה זה, שאין לדעתם בכגון זה לא אונאה ולא ביטול מיקח, \u0003ו\u0004האם \u0003לא? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' יהודה אומר: המוכר ספר תורה, בהמה ומרגלית\u0004 — \u0003אין להן אונאה. אמרו לו\u0004 חכמים: \u0003לא אמרו אלא את אלו\u0004 שהוזכרו קודם לכן באותה משנה, קרקעות, עבדים ושטרות. אבל בכל דבר אחר (ובכלל זה מכירת צמד ובקר) יש דין אונאה ודין ביטול מיקח!","ומתרצים: יש להסביר, כי \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אין דמים ראיה\" נמי דקתני\u0004 \u0005[גם כן ששנו]\u0006 חכמים במשנתנו? \u0003דהוי\u0004 \u0005[שהריהו]\u0006 \u0003ביטול מקח. ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 תירוץ אחר, מדוע לדעת חכמים אין במקרה זה של צמד ובקר ביטול מקח, משום ש\u0003כי אמור רבנן\u0004 \u0005[כאשר אמרו חכמים]\u0006 שיש דין \u0003אונאה וביטול מקח\u0004 — הרי זה דווקא כאשר ההבדל במחיר הוא \u0003ב\u0004שיעור \u0003כדי שהדעת טועה,\u0004 ורק כשאפשר שהיתה זו טעות או רמיה יש בכך דין אונאה. \u0003אבל\u0004 כשההבדל גדול כל כך \u0003בכדי שאין הדעת טועה\u0004 — \u0003לא\u0004 דנים כלל בדין אונאה, ומדוע? — \u0003אימור\u0004 \u0005[אמור]\u0006 ש\u0003מתנה יהב ליה\u0004 \u0005[נתן לו]\u0006 שנותן לו סכום גדול עבור דבר שערכו קטן.","\u0003המוכר את החמור\u0004 — \u0003לא מכר\u0004 עימו את \u0003כליו,\u0004 כלומר, את כלי הריתמה ושאר חפצים שרגילים להניח עליו. \u0003נחום המדי אומר: מכר\u0004 את \u0003כליו. ר' יהודה אומר: פעמים\u0004 שכליו \u0003מכורין, פעמים\u0004 ש\u0003אינן מכורין. כיצד?\u0004 — \u0003היה חמור לפניו וכליו עליו, ואמר לו: \"מכור לי חמורך זה\"\u0004 — \u0003הרי כליו מכורין\u0004 עימו. אם אומר לו: \"האם \u0003חמורך הוא?\u0004 אני רוצה לקנותו\" — \u0003אין כליו מכורין,\u0004 שהרי הוא כקונה חמור סתם, בלי להתייחס לכליו.","ובהסבר המחלוקת במשנתנו, אם כליו של חמור מכורים יחד עמו, \u0003אמר עולא: מחלוקת\u0004 זו היא דווקא \u0003ב\u0004יחס ל\u0003שק\u0004 שעליו, \u0003ודיסקיא\u0004 זוג שקים שמשני צידיו, \u0003וכומני\u0004 שהוא אוכף העשוי לישיבת נשים, שה\u0003תנא קמא סבר\u0004 \u0005[הראשון סבור]\u0006 ש\u0003סתם חמור לרכוב קאי\u0004 \u0005[\u0006הוא \u0005עומד],\u0006 ולכן כלים אלה שאינם לרכיבה אלא למשא, אינם נמכרים עם החמור. \u0003ונחום המדי סבר: סתם חמור למשאוי\u0004 (למשא) \u0003קאי\u0004 \u0005[\u0006הוא \u0005עומד],\u0006 ולכן כלים אלה של משא נמכרים עמו. \u0003אבל אוכף ומרדעת\u0004 (מעין שטיח שתחת האוכף), \u0003קילקלי\u0004 (ריתמה) \u0003וחבק\u0004 (רצועה שקושרים בה את האוכף) — \u0003דברי הכל מכורין,\u0004 שאלו משמשים גם למשא וגם לרכיבה.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו בברייתא, אמר: \u0003\"חמור וכליו אני מוכר לך\"\u0004 — \u0003הרי זה מכר את האוכף ואת המרדעת ואת הקילקלי ואת החבק, אבל לא מכר שק ודיסקיא וכומני. ובזמן שאמר לו: \"היא וכל מה שעליה\u0004 מכורים לך \u0003\"\u0004— \u0003הרי כולן מכורין.\u0004 ונדייק מכאן: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 \u0003\"חמור וכליו\",\u0004 שהזכיר את הכלים במפורש, \u0003הוא דקני\u0004 \u0005[שקונה]\u0006 \u0003אוכף ומרדעת, הא\u0004 \u0005[אבל]\u0006 אם \u0003לא אמר ליה הכי\u0004 \u0005[לו כך]\u0006 — \u0003לא!\u0004","ומשיבים: \u0003הוא הדין דאף על גב\u0004 \u0005[שאף על פי]\u0006 ש\u0003לא אמר ליה\u0004 \u0005[לו]\u0006 \u0003\"חמור וכליו\"\u0004 — \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003אוכף ומרדעת מכורין, והא קא משמע לן\u0004 \u0005[\u0006\u0005ו\u0006דבר \u0005זה השמיע לנו],\u0006 \u0003דאף על גב דאמר ליה\u0004 \u0005[שאף על פי שאמר לו]\u0006 \u0003\"חמור וכליו\",\u0004 מכל מקום \u0003שק ודיסקיא וכומני לא קני\u0004 \u0005[קנה].\u0006","כיון שהוזכר כמה פעמים כומני, שואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"כומני\"\u0004 זה? \u0003אמר רב פפא בר שמואל: מרכבתא דנשי\u0004 \u0005[\u0006אוכף שעשוי \u0005לרכיבת נשים]\u0006 שיושבות לרוחב הבהמה, ולא כדרך רכיבה רגילה.","ועוד לענין המחלוקת במשנתנו, האם המוכר את החמור מכר גם את כליו, \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 לחכמים\u0005]\u0006 שאלה זו: האם דווקא \u0003ב\u0004מקרה שהכלים \u0003עודן עליו,\u0004 על החמור, היא \u0003מחלוקת, אבל בשאינן עליו\u0004 — \u0003מודה להו\u0004 \u0005[להם]\u0006 \u0003נחום המדי\u0004 לחכמים שהכלים אינם מכורים, \u0003או דלמא\u0004 \u0005[שמא]\u0006 דווקא \u0003בשאינן עליו\u0004 היא \u0003מחלוקת, אבל בעודן עליו\u0004 — \u0003מודו ליה רבנן\u0004 \u0005[מודים לו חכמים]\u0006 \u0003לנחום\u0004 המדי שהכלים מכורים? \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו בברייתא: \u0003ובזמן שאמר לו \"הוא וכל מה שעליו\"\u0004 — \u0003הרי כולן מכורין,\u0004 ומשמע שהכלים מצויים עליו.","ומעתה, \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 כי \u0003בעודן עליו מחלוקת, הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 כשיטת \u0005מי היא]?\u0006 — כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא,\u0004 שלמרות שבסתם אינו קונה את הכלים, אם אמר במפורש \"הוא וכל מה שעליו\" — קונה. \u0003אלא אי אמרת\u0004 \u0005[אם אתה אומר]\u0006 כי \u0003בשאין עודן עליו מחלוקת, אבל בעודן עליו דברי הכל מכורין, הא מני\u0004 \u0005[זו\u0006 כשיטת \u0005מי היא]?\u0006 הרי אף לדעת חכמים, גם אם לא אמר במפורש — קנה את הכלים שעליו!","ומשיבים: \u0003לעולם בשאין עודן עליו מחלוקת, ו\u0004הברייתא שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא,\u0004 אלא שמדובר בה במקרה שאין הכלים מצויים על החמור, ולפי זה יש לשנות מעט את נוסח הדברים \u0003ואימא\u0004 \u0005[ואמור\u0006 כך\u0005]:\u0006 \u0003ובזמן שאמר לו \"הוא וכל מה שראוי להיות עליו\",\u0004 כלומר, מה שהוא נושא עליו כרגיל — כולם מכורים.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה ממה ששנינו במשנתנו, \u0003ר' יהודה אומר: פעמים מכורין, פעמים שאינן מכורין,\u0004 והוא מפרט: כיצד? היה חמור לפניו וכליו עליו וכו', \u0003מאי לאו אמאי דקאמר\u0004 \u0005[האם לא על מה שאמר]\u0006 ה\u0003תנא קמא קאי\u0004 \u0005[הראשון עומד,\u0006 מתייחס\u0005]\u0006 \u0003ר' יהודה?\u0004 ומכאן שהמחלוקת בין התנא הראשון ונחום המדי היא במקרה שהכלים על החמור! ודוחים: \u0003לא, ר' יהודה\u0004"],["\u0003מלתא אחריתי קאמר\u0004 \u0005[דבר אחר אמר],\u0006 ואינו מתייחס בהכרח למקרה עליו דובר קודם במשנה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו ממקום אחר, ששנינו במשנה הקודמת: \u0003מכר את הקרון\u0004 — \u0003לא מכר את הפרדות. ו\u0004מסופר כי \u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב תחליפא בר מערבא\u0004 \u0005[בן ארץ ישראל]\u0006 \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' אבהו\u0004 ברייתא זו: \u0003מכר את הקרון\u0004 — \u0003מכר את הפרדות, ואמר ליה\u0004 \u0005[לו]\u0006 ר' אבהו: \u0003והא אנן\u0004 \u0005[והרי אנו]\u0006 \u0003\"לא מכר\" תנן\u0004 \u0005[שנינו]!\u0006 \u0003ואמר ליה\u0004 \u0005[לו]\u0006 רב תחליפא: \u0003איסמייה\u0004 \u0005[\u0006האם \u0005אמחוק אותה]\u0006 את הברייתא הזו, מפני שהיא משובשת? \u0003ואמר ליה\u0004 \u0005[לו]\u0006 ר' אבהו: \u0003לא, תתרגם מתניתך\u0004 \u0005[תרגם,\u0006 הסבר \u0005את משנתך]\u0006 \u0003ב\u0004מקרה שהפרדות \u0003אדוקים\u0004 (קשורים) \u0003בו\u0004 בקרון;","\u0003מכלל\u0004 דברי ר' אבהו נלמד \u0003דמתניתין\u0004 \u0005[שמשנתנו]\u0006 האומרת שלא מכר את הפרדות, מדברת \u0003בשאין אדוקים בו, ומדרישא\u0004 \u0005[ומתוך שראשה],\u0006 כלומר, המשנה הקודמת, מדברת \u0003בשאין עודן עליו\u0004 ואינם קשורים בו, \u0003סיפא נמי\u0004 \u0005[סופה גם כן],\u0006 כלומר, משנתנו, בענין חמור וכליו, מדברת \u0003בשאין עודן עליו!\u0004","ודוחים: \u0003אדרבה\u0004 \u0005[להיפך],\u0006 \u0003אימא רישא\u0004 \u0005[אמור\u0006 את \u0005ראשה],\u0006 כלומר, את המשנה הקודמת לזו: המוכר ספינה מכר את התורן וכו' \u0003אבל לא מכר לא את העבדים ולא את האנתיקי. ואמרינן\u0004 \u0005[ואמרנו],\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אנתיקי\"? אמר רב פפא: עיסקא דבגוה\u0004 \u0005[הסחורה\u0006 שנמצאת \u0005בתוכה],\u0006 \u0003ו\u0004אם כן \u0003מדרישא\u0004 \u0005[מכיון שראשה],\u0006 כלומר, אותה משנה שבתחילת הפרק, מדברת \u0003בעודן עליו,\u0004 שהרי מדובר בעסק הנמצא עליה. \u0003סיפא נמי\u0004 \u0005[סופה גם כן]\u0006 משנתנו בענין חמור, מדברת \u0003בעודן עליו! אלא\u0004 על כרחנו צריך לומר שה\u0003תנא מילי מילי קתני\u0004 \u0005[דברים דברים,\u0006 כל אחד לחוד, \u0005שנה],\u0006 ואין ללמוד מדין אחד על חבירו.","\u0003אמר אביי: ר' אליעזר ורבן שמעון בן גמליאל ור' מאיר ור' נתן וסומכוס ונחום המדי, כולהו סבירא להו\u0004 \u0005[כולם סבורים הם]:\u0006 \u0003כי מזבין איניש מידי\u0004 \u0005[כאשר מוכר אדם דבר],\u0006 \u0003איהו\u0004 \u0005[אותו]\u0006 \u0003ו\u0004את \u0003כל תשמישתיה מזבין\u0004 \u0005[תשמישיו\u0006 הוא \u0005מוכר\u0006 איתו\u0005].\u0006","ופירוט השיטות: \u0003ר' אליעזר\u0004 — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' אליעזר אומר: המוכר את בית הבד\u0004 — \u0003מכר את הקורה\u0004 שבה כובשים את הזיתים, למרות שהיא מיטלטלת. \u0003רבן שמעון בן גמליאל\u0004 — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003רבן שמעון בן גמליאל אומר: המוכר את העיר\u0004 — \u0003מכר את הסנטר\u0004 (שומר העיר). \u0003ר' מאיר\u0004 — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' מאיר אומר: מכר את הכרם\u0004 — \u0003מכר תשמישי הכרם. ר' נתן וסומכוס\u0004 — \u0003ביצית ודוגית,\u0004 שלדעת שניהם סירות קטנות הנמכרות יחד עם הספינה. \u0003נחום המדי\u0004 — \u0003הא דאמרן\u0004 \u0005[זה שאמרנו]\u0006 במשנתנו.","שנינו במשנה ש\u0003ר' יהודה אומר\u0004 בענין כלי החמור כשמכר את החמור עצמו: \u0003פעמים\u0004 שהם \u0003מכורין\u0004 פעמים שאינם מכורים. כיצד? היה חמור לפניו וכליו עליו ואמר לו: \"מכור לי חמורך זה\" — הרי כליו מכורין. \"חמורך הוא\" — אין כליו מכורין. ושואלים: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 כשאומר \u0003\"\u0004מכור לי \u0003חמורך זו\", ומאי שנא\u0004 \u0005[ומה שונה]\u0006 אם אומר \u0003\"חמורך הוא\"?\u0004","\u0003אמר רבא:\u0004 כשאומר \u0003\"חמורך זו\"\u0004 — \u0003ידע דחמרא דידיה\u0004 \u0005[יודע\u0006 הוא \u0005שהחמור שלו]\u0006 \u0003הוא, והאי דקא אמר ליה\u0004 \u0005[וזה שאומר לו]\u0006 \u0003\"זו\", משום כליו קאמר ליה\u0004 \u0005[אומר לו],\u0006 אבל אם אומר \u0003\"חמורך הוא\"\u0004 — שהוא \u0003לא ידע דחמרא דידיה\u0004 \u0005[יודע שהחמור שלו]\u0006 \u0003הוא, והכי קאמר ליה\u0004 \u0005[וכך אמר לו]:\u0006 האם \u0003חמורך הוא\u0004 זה, \u0003ש\u0004אם כן \u0003תמכרנה לי?\u0004 ואם כן התכוון לחמור סתם, ולאו דוקא על כליו.","\u0003המוכר את החמור\u0004 הנקיבה — \u0003מכר\u0004 עמה \u0003את הסיח,\u0004 בנה, המצוי איתה. אבל אם \u0003מכר את הפרה\u0004 — \u0003לא מכר את בנה\u0004 עימה. אם \u0003מכר\u0004 חפירה או מיכל העשוים ל\u0003אשפה\u0004 — \u0003מכר\u0004 גם את \u0003זבלה\u0004 שבתוכה. \u0003מכר בור\u0004 — \u0003מכר מימיה. מכר כוורת\u0004 — \u0003מכר דבורים\u0004 שבה. \u0003מכר שובך\u0004 — \u0003מכר יונים\u0004 שבו.","שנינו כי הסייח נמכר עם אמו האתון, אבל העגל אינו נמכר עם אמו הפרה. ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 \u0003אי דאמר ליה\u0004 \u0005[אם שאומר לו]\u0006 \u0003\"היא ובנה\u0004 מכורים לך \u0003\", אפילו פרה ובנה נמי\u0004 \u0005[גם כן]\u0006 יימכרו, \u0003אי\u0004 \u0005[אם]\u0006 במקרה ש\u0003לא אמר ליה\u0004 \u0005[לו]\u0006 \u0003\"היא ובנה\", אפילו\u0004 כשמוכר לו \u0003חמור נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 יימכר הסייח!","\u0003אמר רב פפא:\u0004 מדובר במקרה \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 המוכר: \u0003\"חמור מניקה\" ו\u0004כיוצא בזה \u0003\"פרה מניקה\" אני מוכר לך.\u0004 ומעתה, \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003פרה, איכא למימר\u0004 \u0005[יש לומר]\u0006 כי \u0003לחלבה בעי לה\u0004 \u0005[צריך\u0006 הקונה \u0005אותה]\u0006 ולכן מדגיש לו שהוא מוכר לו פרה שיש לה חלב, \u0003אלא חמור מאי קאמר ליה\u0004 \u0005[לשם מה אומר לו]\u0006 שהיא מניקה? והרי אין אדם צריך לחלב של חמור! \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003היא ובנה קאמר ליה\u0004 \u0005[אומר לו].\u0006 אגב מעירים: \u0003ואמאי קרי ליה\u0004 \u0005[ומדוע\u0006 במשנתנו \u0005קורא לו]\u0006 לבן החמור \u0003\"סיח\"? שמהלך אחר סיחה נאה,\u0004 כלומר, שאינו צריך שיכריחו אותו כחמור זקן, אלא בא בקלות אל מי שקורא לו.","אגב כך מביאים ענין מוסרי שמוזכר בו נושא זה, \u0003אמר ר' שמואל בר נחמן אמר ר' יוחנן, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"על כן יאמרו המושלים\u0004 בואו חשבון תבנה ותכונן עיר סיחון.","כי אש יצאה מחשבון להבה מקרית סיחון אכלה ער מואב בעלי במות ארנון\u0003\"\u0004 (במדבר כא, כז– כח)? \u0003\"המשלים\"\u0004 — \u0003אלו המושלים ביצרם,\u0004 הם יאמרו: \u0003\"באו חשבון\"\u0004 — וכוונתו: \u0003בואו ונחשב חשבונו של עולם,\u0004 ומהו? — \u0003הפסד\u0004 שנגרם לו מעשיית \u0003מצוה כנגד שכרה, ו\u0004כן \u0003שכר עבירה\u0004 הנאה ורווח שיש לו ממנה \u0003כנגד הפסדה.\u0004","\u0003\"תבנה ותכונן\"\u0004 — כוונתו \u0003אם אתה עושה כן, תבנה בעולם הזה ותכונן\u0004 (יושלם בניינך) \u0003לעולם הבא. \"עיר סיחון\"\u0004 — כוונתו: \u0003אם משים אדם עצמו כעיר\u0004 (בן חמור) \u0003זה שמהלך אחר סיחה נאה,\u0004 ואותו אדם מתפתה כך בקלות והולך אחרי יצרו, \u0003מה כתיב\u0004 \u0005[נאמר]\u0006 \u0003אחריו? \"כי אש יצאה מחשבון\" וגו'\u0004 — \u0003תצא אש מ\u0004אותם ה\u0003מחשבין\u0004 את חשבון עולמם, \u0003ותאכל את שאינן מחשבין\u0004 אלא נוהגים הפקר בעצמם.","\u0003ו\u0004כן תצא \u0003\"להבה מקרית סיחן\"\u0004 — \u0003מקרית צדיקים שנקראו שיחין\u0004 (אילנות). \u0003\"אכלה ער מואב\"\u0004 — \u0003זה המהלך אחר יצרו כעיר זה\u0004 (\"ער\") \u0003שמהלך אחר סיחה נאה.\u0004 ואת \u0003\"בעלי במות ארנן\"\u0004 — \u0003אלו גסי הרוח\u0004 שהם מגביהים עצמם. ומעירים: ודבר זה הוא כמו ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003כל אדם שיש בו גסות הרוח נופל בגיהנם.\u0004","וממשיך הכתוב: \"ונירם אבד חשבון עד דיבון ונשים עד נופח אשר עד מידבא\" (במדבר כא, ל), וכך דורשים אותו: \u0003\"ונירם\"\u0004 — \u0003אמר רשע: אין רם,\u0004 כלומר, אין כוח עליון בעולם; \u0003\"אבד חשבון\"\u0004 — \u0003אבד חשבונו של עולם\u0004 ואין חשבון והשגחה. \u0003\"עד\u0004 \u0003דיבן\"\u0004 — \u0003אמר הקדוש ברוך הוא: המתן עד שיבא דין; \"ונשים\u0004"],["\u0003עד נפח\"\u0004 — \u0003עד שתבא אש שאינה צריכה ניפוח\u0004 כדי לבעור, שהיא אש הגיהנם, והיא תאכלנו. \u0003\"עד מידבא\"\u0004 — \u0003עד שתדאיב\u0004 (תכאיב) \u0003נשמתן. ואמרי לה\u0004 \u0005[ו\u0006יש \u0005אומרים אותה\u0006 שמועה באופן אחר\u0005]:\u0006 \u0003עד דעביד מאי דבעי\u0004 \u0005[שיעשה\u0006 הקדוש ברוך הוא \u0005מה ש\u0006הוא \u0005רוצה]\u0006 ויענישם כראוי להם.","\u0003אמר רב יהודה אמר רב: כל הפורש מדברי תורה\u0004 — \u0003אש אוכלתו, שנאמר: \"ונתתי את פני בהם מהאש יצאו והאש תאכלם\"\u0004 (יחזקאל טו, ז). כי התורה נמשלה לאש (\"הלא כה דברי כאש\". ירמיה כג, כט) והפורש ממנה (\"מהאש יצאו\") נענש שאש של גיהנם אוכלתו.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 בשם \u0003ר' יונתן: כל הפורש עצמו מדברי תורה\u0004 — \u0003נופל בגיהנם, שנאמר: \"אדם תועה מדרך השכל בקהל רפאים ינוח\"\u0004 (משלי כא, טז), שהיוצא מ\"דרך השכל\", דרך התורה, מגיע למקום הרפאים. \u0003ואין\u0004 מקום \u0003רפאים אלא גיהנם, שנאמר: \"ולא ידע כי רפאים שם בעמקי שאול קראיה\"\u0004 (משלי ט, יח).","שנינו במשנה שאם \u0003מכר אשפה\u0004 — \u0003מכר זבלה וכו'. תנן התם\u0004 \u0005[שנינו\u0006 במשנה \u0005שם\u0006 במסכת מעילה\u0005]:\u0006 \u0003כל\u0004 דבר \u0003הראוי\u0004 לשמש קרבן \u0003למזבח ולא\u0004 ראוי \u0003לבדק הבית,\u0004 לצרכי בית המקדש עצמו, או ראוי \u0003לבדק הבית ולא למזבח,\u0004 כגון זהב או אבנים, וכן כל דבר שאינו ראוי כמו שהוא \u0003לא למזבח ולא לבדק הבית,\u0004 ודינו שימכר ויפלו דמיו להקדש, כל אלה, אם הקדיש אותם — \u0003מועלין בהן ובמה שבתוכן,\u0004 שאם משתמש בהם לצורך הדיוט לאחר שהוקדשו — עובר על איסור מעילה, וחייב להביא קרבן כפרה.","\u0003כיצד?\u0004 אם \u0003הקדיש בור מלאה מים, אשפות מלאות זבל, שובך מלא יונים, שדה מלאה עשבים, אילן נשוי\u0004 (נושא, מלא) \u0003פירות\u0004 — \u0003מועלין בהן ובמה שבתוכן;\u0004","\u0003אבל\u0004 אם \u0003הקדיש בור\u0004 \u0003ואחר כך נתמלא\u0004 הבור \u0003מים,\u0004 או שהקדיש \u0003אשפה ואחר כך נתמלאה זבל, שובך ואחר כך נתמלא יונים, אילן ואחר כך נשא פירות, שדה ואחר כך נתמלאה עשבים\u0004 — \u0003מועלין בהן ואין מועלין במה שבתוכן,\u0004 אלו \u0003דברי ר' יהודה; ר' יוסי אומר: הקדיש את השדה ואת האילן\u0004 — \u0003מועלין בהן ובגידוליהם, מפני שהן גידולי הקדש\u0004 שהם צומחים מתוך דבר מוקדש.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר רבי: נראין דברי ר' יהודה\u0004 \u0003בבור ושובך,\u0004 שאם הקדיש אותם כשהם ריקים — לא הוקדש מה שנוסף בתוכם לאחר מכן, \u0003ו\u0004נראים \u0003דברי ר' יוסי\u0004 — \u0003בשדה ואילן.\u0004 ותוהים על דברי רבי: \u0003האי מאי\u0004 \u0005[זה מהו]?\u0006 \u0003בשלמא\u0004 \u0005[נניח]\u0006 זה שהוא אומר \u0003נראין דברי ר' יהודה בבור ושובך\u0004 — \u0003מכלל\u0004 הדברים עולה \u0003דפליג\u0004 \u0005[שחולק]\u0006 ר' יהודה על ר' יוסי לענין \u0003שדה ואילן,\u0004 ואכן ר' יהודה אומר כך במפורש, שאין מועלים בפירות שנוספו להם לאחר שהקדישם.","\u0003אלא\u0004 כשהוא אומר \u0003נראין דברי ר' יוסי בשדה ואילן\u0004 — \u0003מכלל\u0004 דבריו עולה \u0003דפליג\u0004 \u0005[שחולק]\u0006 ר' יוסי על ר' יהודה גם \u0003בבור ושובך?\u0004 וכי אפשר לפרש כן? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ר' יוסי שדה ואילן קאמר\u0004 \u0005[אומר]\u0006 שגידוליהם צומחים מתוכם, ואין נימוק זה שייך בבור ושובך, שאין המים והיונים באים מתוכם!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שר' יוסי \u0003לדבריו\u0004 של \u0003ר' יהודה קאמר\u0004 \u0005[אומר הוא],\u0006 שאף לשיטת ר' יהודה ראוי לאסור בשדה ואילן משום שהם גידולי הקדש, אף שר' יוסי עצמו סבור שגם בור ושובך מכניסים לרשות ההקדש מה שבא לתוכם, \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' יוסי: אין אני רואה\u0004 (מקבל) \u0003דבריו של ר' יהודה בשדה ואילן, מפני שהן גידולי הקדש,\u0004 ונלמד מכאן: \u0003בשדה ואילן הוא\u0004 ש\u0003אינו רואה, הא\u0004 \u0005[הרי]\u0006 \u0003בבור ושובך רואה!\u0004","ומסבירים: \u0003הכי קאמר\u0004 \u0005[כך אומר]\u0006 רבי: \u0003נראין דברי ר' יהודה לר' יוסי\u0004 \u0003בבור ושובך\u0004 שאין מעילה במה שנוסף בתוכם לאחר זמן, \u0003שאף ר' יוסי לא נחלק עליו אלא בשדה ואילן, אבל בבור ושובך מודי ליה\u0004 \u0005[מודה לו].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אם \u0003הקדישן\u0004 כשהם \u0003ריקנין ואחר כך נתמלאו\u0004 — \u0003מועלין בהן ואין מועלין במה שבתוכן. ר' אלעזר בר' שמעון אומר: אף מועלין במה שבתוכן.\u0004","\u0003אמר רבה: מחלוקת\u0004 זו היא \u0003בשדה ואילן,\u0004 שה\u0003תנא קמא סבר לה\u0004 \u0005[הראשון סבור]\u0006 \u0003כ\u0004דעת \u0003ר' יהודה\u0004 שהזכרנו, \u0003ור' אלעזר בר' שמעון סבר לה\u0004 \u0005[סבור]\u0006 \u0003כר' יוסי, אבל בבור ושובך\u0004 — \u0003דברי הכל מועלין בהן ואין מועלין במה שבתוכן.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי, ואלא\u0004 והרי \u0003הא דתניא\u0004 \u0005[זו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003הקדישן מלאין\u0004 — \u0003מועלין בהן ובמה שבתוכן, ור' אלעזר בר' שמעון מחליף,\u0004 כלומר, הופך את הדברים וסבור שאם הקדישם מלאים — אין מועלים במה שבתוכם."],["\u0003ואי\u0004 \u0005[ואם]\u0006 מדובר \u0003בשדה ואילן, אמאי\u0004 \u0005[מדוע]\u0006 \u0003מחליף?\u0004 והרי אם יש דין מעילה בפירות שאינם עליהם עדיין, כל שכן שיהא דין מעילה במה שכבר נמצא עליהם בזמן ההקדש! \u0003אלא\u0004 יש להפוך את הגרסה, וכך לומר, \u0003אמר רבה: מחלוקת\u0004 זו, בין ר' אלעזר בר' שמעון ותנא קמא, היא \u0003בבור ושובך, אבל בשדה ואילן\u0004 — \u0003דברי הכל מועלין בהן ובמה שבתוכן.\u0004","ושואלים: \u0003ובבור ושובך\u0004 — \u0003בריקנין במאי פליגי\u0004 \u0005[במה\u0006 הם \u0005חולקים]\u0006 \u0003ובמלאין במאי פליגי\u0004 \u0005[במה\u0006 הם \u0005חולקים]?\u0006 ומסבירים: \u0003בריקנין פליגי\u0004 \u0005[חולקים\u0006 הם\u0005]\u0006 \u0003בפלוגתא\u0004 \u0005[במחלוקת]\u0006 של \u0003ר' מאיר ורבנן\u0004 \u0005[וחכמים],\u0006 שה","\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003סבר לה כרבנן\u0004 \u0003דאמרי\u0004 \u0005[סבור כ\u0006דעת \u0005חכמים שאומרים]:\u0006 \u0003אין אדם מקנה דבר שלא בא לעולם,\u0004 ומשום כך אין אדם יכול להקדיש מים או יונים שיבואו לשם בעתיד, כאשר אינם מצויים כעת, \u0003ור' אלעזר בר' שמעון סבר\u0004 \u0005[סבור]\u0006 \u0003כר' מאיר,\u0004 ש\u0003אמר: אדם מקנה דבר שלא בא לעולם.\u0004","ותוהים על כך: \u0003אימור\u0004 \u0005[אמור]\u0006 ש\u0003שמעת ליה\u0004 \u0005[אותו]\u0006 את \u0003ר' מאיר\u0004 שאומר שיכול להקנות דבר שלא בא לעולם \u0003כגון\u0004 ב\u0003פירות דקל דעבידי דאתו\u0004 \u0005[שעשויים שיבואו],\u0006 שדרך העולם שיצמחו, וסבור ר' מאיר שיכול להקנותם אף שעדיין אינם בעולם, ואולם \u0003הני מי יימר דאתו\u0004 \u0005[אלה,\u0006 מים ויונים, \u0005מי יאמר\u0006 כלל \u0005שיבואו]?\u0006 \u0003אמר רבא, משכחת לה\u0004 \u0005[מוצא אתה\u0006 דוגמא\u0005]\u0006 שאלה דרכם לבוא, כגון \u0003במים הבאין דרך חצרו לבור,\u0004 שהמים יורדים לבור זה מחצרו עם ירידת הגשמים, ואינו צריך למלא את הבור מים, \u0003ו\u0004כן ב\u0003יונים הבאין דרך שובכו\u0004 המלא יונים \u0003לשובך\u0004 ריק זה.","ושואלים עוד לדרך זו, \u0003וב\u0004בור ושובך \u0003מלאים במאי פליגי\u0004 \u0005[במה\u0006 הם \u0005חלוקים]?\u0006 \u0003אמר רבא: כגון שהקדיש בור סתם, ור' אלעזר בר' שמעון סבר לה כאבוה\u0004 \u0005[סבור כאביו],\u0006 ש\u0003אמר\u0004 ר' שמעון: \u0003דנין דין גבוה מדין הדיוט,\u0004 שדין המקדיש לה' (לגבוה) הריהו כדין אדם המוכר לחבירו (הדיוט),","\u0003מה דין הדיוט\u0004 — \u0003מצי אמר\u0004 \u0005[יכול לומר]\u0006 המוכר: \u0003בירא זביני\u0004 \u0005[בור מכרתי]\u0006 \u0003לך, מיא\u0004 \u0005[\u0006את \u0005המים]\u0006 שבתוכו \u0003לא זביני\u0004 \u0005[מכרתי]\u0006 \u0003לך,\u0004 \u0003אף דין גבוה\u0004 — \u0003בירא אקדיש\u0004 \u0005[בור הקדיש],\u0006 \u0003מיא\u0004 \u0005[מים]\u0006 שבתוכו \u0003לא אקדיש\u0004 \u0005[הקדיש],\u0006 \u0003ו\u0004ה\u0003תנא קמא סבר\u0004 \u0005[הראשון סבור]:\u0006 \u0003אין דנין דין גבוה מדין הדיוט,\u0004 והמקדיש מקדיש בעין יפה, את הבור ומה שבתוכו, גם כשאינו מפרש.","ושואלים: \u0003ודין הדיוט לא?\u0004 וכי המוכר בור לא מכר גם את המים שבתוכו? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003מכר בור\u0004 — \u0003מכר מימיו! אמר רבא: מתניתין יחידאה\u0004 \u0005[משנתנו\u0006 כדעת \u0005יחיד]\u0006 \u0003היא\u0004 וחכמים חלוקים עליה. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 \u0003מכר בור\u0004 — \u0003לא מכר מימיו. ר' נתן אומר: מכר בור\u0004 — \u0003מכר מימיו,\u0004 ואם כן משנתנו זו היא בעצם דעת יחיד של ר' נתן ולא דעת הרבים. אבל המחלוקת בין ר' אלעזר בר' שמעון וחביריו היא לפי שיטת חכמים, הסבורים שהמים אינם מכורים עם בור."],["\u0003הלוקח\u0004 (קונה) \u0003פירות שובך מחבירו,\u0004 שקונה ממנו כל היונים שיוולדו בשובכו בשנה מסויימת — \u0003מפריח,\u0004 משאיר למוכר, \u0003בריכה ראשונה,\u0004 הזוג הראשון של גוזלים שנולדו בשובך באותה שנה, שאם יטול אותם לעצמו ולא ישאיר אותם בשובך — יפרחו גם היונים שהיו שם כבר, והרי אותן לא מכר. אם קונה \u0003פירות כוורת,\u0004 כלומר, דבורים היוצאות מכוורתו במשך השנה — \u0003נוטל\u0004 הקונה \u0003שלשה נחילים\u0004 מחזורים של ולדות, \u0003ו\u0004לאחר מכן \u0003מסרס\u0004 המוכר את הדבורים, כדי שלא יעמידו עוד וולדות, אלא שיעשו עבורו דבש. הקונה \u0003חלות דבש\u0004 — \u0003מניח\u0004 הקונה למוכר \u0003שתי חלות\u0004 לקיום הדבורים שנשארות בכוורת. אם מכר לו \u0003זיתים\u0004 עצי זית, כדי \u0003לקוץ\u0004 (לקצוץ) אותם — \u0003מניח\u0004 הקונה למוכר \u0003שתי גרופיות\u0004 (יחורים, ענפים שנוטעים אותם), ואת הגזע ושאר הענפים יקח הקונה.","במשנה שנינו שהקונה פירות שובך משאיר למוכר בריכה ראשונה, ומתקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003בריכה ראשונה ושניה\u0004 משאיר למוכר! \u0003אמר רב כהנא, לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003הא\u0004 \u0005[זו]\u0006 ששנינו במשנה, כוונתו — \u0003לה,\u0004 כלומר, לבריכה הראשונה של גוזלים שמשאיר בשובך, שכדי שתישאר זו בשובך צריך לשייר גם לה בריכה ראשונה שלה. \u0003הא\u0004 \u0005[זו]\u0006 ששנינו בברייתא — \u0003לאמה,\u0004 לזוג היונים הראשון שנשאר בשובך. שמשאיר בריכה ראשונה עבורה ובריכה שניה עבור \"בתה\".","ושואלים: \u0003מאי שנא\u0004 \u0005[מה שונה]\u0006 \u0003אמה?\u0004 — \u0003דמיצטוותא אברתא ואזוגא דשבקינן\u0004 \u0005[ש\u0006היא \u0005מתחברת עם בתה ועם בן הזוג שמניחים]\u0006 \u0003לה,\u0004 ומשום כך לא תברח מהשובך, \u0003איהי נמי תיצטוותא\u0004 \u0005[היא\u0006 הבת \u0005גם כן תצטרף]\u0006 עם \u0003אמה, ואזוגא דשבקינן\u0004 \u0005[ועם בן הזוג שמניחים]\u0006 \u0003לה!\u0004 ומשיבים: \u0003אמה אברתא מיצטוותא\u0004 \u0005[האם עם הבת מצטרפת],\u0006 \u0003ברתא\u0004 \u0005[הבת]\u0006 עם \u0003אמה לא מיצטוותא\u0004 \u0005[מצטרפת].\u0006 וצריכה משום כך שאף ולדותיה שלה יהיו עמה כדי שתישאר.","שנינו במשנה: הלוקח \u0003פירות כוורת\u0004 — \u0003נוטל שלשה נחילין ו\u0004לאחר מכן המוכר \u0003מסרס.\u0004 ושואלים: \u0003במה,\u0004 כיצד, \u0003מסרסן? אמר רב יהודה אמר שמואל: בחרדל\u0004 שמאכילן. \u0003אמרי במערבא\u0004 \u0005[אמרו בארץ ישראל]\u0006 \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' יוסי בר חנינא: לא\u0004 ה\u0003חרדל\u0004 עצמו \u0003מסרסן, אלא מתוך שפיהן חד\u0004 (צורב) מפני חריפות החרדל, הריהן \u0003חוזרות ואוכלות את דובשנן\u0004 וכך מפסיקות ליצור עוד נחילים נוספים, ומייצרות דבש עבור המוכר.","\u0003ר' יוחנן אמר\u0004 ש\"מסרס\", יש להבינו במובן אחר: \u0003נוטל שלשה נחילין בסירוס\u0004 = בדילוג, שהקונה מקבל נחיל ראשון, שלישי וחמישי, והאחרים נשארים בידי המוכר. \u0003במתניתא תנא\u0004 \u0005[בברייתא שנה]:\u0006 \u0003נוטל\u0004 הקונה \u0003שלשה נחילין\u0004 ראשונים \u0003בזה אחר זה,\u0004 ונחילים היוצאים \u0003מכאן ואילך\u0004 — \u0003נוטל אחת ומניח אחת.\u0004","שנינו במשנה שהלוקח \u0003חלות דבש\u0004 — \u0003מניח שתי חלות וכו'. אמר רב כהנא: דבש\u0004 כל זמן שהוא \u0003בכוורת אינו יוצא מידי מאכל לעולם,\u0004 שתמיד נחשב הוא כמאכל אדם, לענין דיני טומאה. ומעירים: \u0003אלמא קסבר\u0004 \u0005[מכאן\u0006 ש\u0005הוא סבור]\u0006 כי דבש \u0003לא בעי\u0004 \u0005[צריך]\u0006 \u0003מחשבה\u0004 לאוכלו, כדי שיקבל טומאה, אלא מעצמו הוא נחשב כמוכשר לטומאה.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]:\u0006 \u0003דבש\u0004 ש\u0003בכוורת\u0004 — \u0003אינו\u0004 נחשב לענין טומאה \u0003לא אוכל ולא משקה! אמר אביי: לא צריכא\u0004 \u0005[צריכה]\u0006 הלכה זו שאינו אוכל ולא משקה, \u0003אלא לאותן שתי חלות\u0004 האמורות במשנתנו, שאינן מיועדות לאכילה, אלא רק לצורך הדבורים. \u0003רבא אמר:\u0004 משנה זו כדעת \u0003ר' אליעזר היא,\u0004"],["\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003כוורת דבורים\u0004 — \u0003ר' אליעזר אומר: הרי היא כקרקע\u0004 לענין דרכי קנין ועוד, \u0003ו\u0004לכן \u0003כותבין עליה פרוזבול,\u0004 שהוא שטר שתיקנו חכמים שמוסר מלווה לבית הדין על חובות שחייבים לו, כדי שלא תשמטם שנת השמיטה, ואין כותבים אותו אלא אם יש ללווה קרקע כלשהי.","\u0003ואינה מקבלת טומאה במקומה,\u0004 שכל זמן שהיא צמודה לקרקע הריהי כקרקע שאינה נטמאת, \u0003והרודה\u0004 (מוציא דבש) \u0003ממנה בשבת\u0004 — \u0003חייב חטאת\u0004 כמי שעוקר דבר מן הקרקע. ולשיטה זו אין הדבש נחשב כאוכל לקבל טומאה, שהרי מחובר הוא.","\u0003וחכמים אומרים:\u0004 כוורת היא כשאר מיטלטלים, ולכן \u0003אין כותבין עליה פרוזבול, ואינה כקרקע\u0004 לענין מכר, אלא נמכרת כמיטלטלים, \u0003ומקבלת טומאה\u0004 אף \u0003במקומה, והרודה ממנה בשבת\u0004 — \u0003פטור.\u0004 ולפיכך אף הדבש שבתוכה תלוש הוא, ומקבל טומאה, וכדברי רב כהנא לעיל.","אגב ענין זה מביאים את מה ש\u0003אמר ר' אלעזר: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' אליעזר?\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויטבל אותה ביערת הדבש\"\u0004 (שמואל א יד, כז), שטבל יונתן את מטהו בחלת דבש, \u0003וכי מה ענין יער אצל דבש,\u0004 ומדוע קוראים לחלה \"יערת דבש\"? \u0003אלא לומר לך\u0004 שהדבש שבכוורת הריהו כיער, \u0003מה יער\u0004 — \u0003התולש ממנו בשבת חייב חטאת, אף\u0004 כוורת \u0003דבש\u0004 — \u0003הרודה ממנו בשבת חייב חטאת.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו: \u0003דבש הזב מכוורתו\u0004 — \u0003אינו לא אוכל ולא משקה; בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003אביי ניחא\u0004 \u0005[נוח\u0006 הדבר\u0005],\u0006 שהרי הוא אומר שמדובר בשתי החלות שבכוורת שהן מיוחדות לדבורים,","\u0003אלא ל\u0004שיטת \u0003רבא קשיא\u0004 \u0005[קשה],\u0006 שהרי אף לדברי ר' אליעזר, מאחר שיצא הדבש מן הכוורת שוב אין דינו כמחובר! \u0003אמר רב זביד: כגון שזב\u0004 הדבש מן הכוורת \u0003על גבי כלי מאוס\u0004 ואינו ראוי לאכילת אדם. \u0003רב אחא בר יעקב אמר: כגון שזב על גבי קשקשין\u0004 עשבים וקש, שאינו ניתן למאכל.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 עוד ממה ששנינו: \u0003דבש\u0004 ש\u0003בכוורתו\u0004 — \u0003אינו לא אוכל ולא משקה,\u0004 אם \u0003חישב עליו לאכילה\u0004 — \u0003מטמא טומאת אוכלין.\u0004 חישב עליו \u0003למשקין\u0004 — \u0003מטמא טומאת משקין; בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003אביי ניחא\u0004 \u0005[נוח\u0006 הדבר\u0005],\u0006 שאף כאן מדובר באותן שתי חלות, שאם חזר וחשב על הדבש שרצונו לאוכלו — הריהו חוזר להיחשב כמאכל אדם.","\u0003אלא לרבא\u0004 שהסביר כי הברייתא לפיה הדבש נחשב מאכל ולא משקה דעת ר' אליעזר היא — \u0003קשיא\u0004 \u0005[קשה]\u0006 מברייתא זו, שהיא בוודאי כדברי חכמים, ובניגוד לדברי רב כהנא!","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך\u0004 \u0003רבא, תריץ הכי\u0004 \u0005[תרץ,\u0006 הסבר, \u0005כך]\u0006 את הברייתא גם כן לשיטת ר' אליעזר: אם \u0003חישב עליו לאכילה\u0004 — \u0003אינו מטמא טומאת אוכלין,\u0004 אם חישב עליו \u0003למשקין\u0004 — \u0003אינו מטמא טומאת משקין.\u0004 ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב כהנא: דבש בכוורתו\u0004 — \u0003מטמא טומאת אוכלין שלא במחשבה,\u0004 שאינו צריך לחשוב עליו שיהא כמאכל אדם, אלא הוא נחשב כאוכל מעצמו.","שנינו במשנה שהקונה מחבירו \u0003זיתים לקוץ\u0004 — \u0003מניח\u0004 מן הזית למוכר \u0003שתי גרופיות. תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הלוקח אילן מחבירו לקוץ\u0004 — \u0003מגביה מן הקרקע טפח וקוצץ\u0004 למעלה ממנו, והאילן יחזור ויצמח מאותו טפח. אם קנה ממנו \u0003בתולת השקמה\u0004 שעדיין לא נקצצה — מגביה \u0003שלשה טפחים.\u0004 קנה ממנו \u0003סדן השקמה\u0004 שכבר נקצץ פעם ושורשיו חזקים — מגביה \u0003שני טפחים.\u0004 \u0003בקנים ובגפנים\u0004 — חותך \u0003מן הפקק\u0004 (הקשר) שיש בהם \u0003ולמעלה,\u0004 והם יחזרו ויצמחו מן הקשר. \u0003בדקלים ובארזים\u0004 — \u0003חופר ומשרש\u0004 (עוקר את השורש), \u0003לפי שאין גזען מחליף\u0004 (חוזר וצומח) לאחר קציצה, וכיון שלא יצמחו עוד — אינו צריך להשאיר דבר.","ושואלים: \u0003ו\u0004ב\u0003בתולת השקמה\u0004 האם \u0003שלשה טפחים בעינן\u0004 \u0005[צריכים אנו]?\u0006 \u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: \u0003אין קוצצין בתולת השקמה בשביעית, מפני שהיא עבודה,\u0004 שהרי על ידי כך צומחת השקמה יותר.","\u0003ר' יהודה אומר: כדרכו אסור\u0004 לקצוץ, \u0003אלא מגביה עשרה טפחים וקוצץ, או גומם\u0004 (חותך) \u0003מעם הארץ\u0004 בגובה הקרקע, ואינו משאיר דבר מלמעלה, שבאופנים אלו אין מעודדים את הגידול, ואף מזיקים לו. ומעתה נדייק מכאן: \u0003מעם הארץ הוא דקשי\u0004 \u0005[שקשה]\u0006 לאילן ואינו מצמיח, \u0003הא אידך מעלי לה\u0004 \u0005[הרי\u0006 אופן \u0005אחר מעולה לו]\u0006 אפילו בפחות משלושה טפחים!","\u0003אמר אביי,\u0004 כך צריך לפרש: \u0003שלשה טפחים מעלי\u0004 \u0005[מועיל]\u0006 \u0003לה,\u0004 \u0003מעם הארץ ודאי קשי\u0004 \u0005[קשה]\u0006 \u0003לה\u0004 ומותר אף בשביעית. \u0003מכאן ואילך,\u0004 כלומר, גבוה יותר מן הארץ עד שלושה טפחים — הרי זה \u0003לא מקשי קשי\u0004 \u0005[קשה]\u0006 \u0003לה ולאו עלויי מעלי\u0004 \u0005[ולא מועיל]\u0006 \u0003לה,\u0004 \u0003גבי\u0004 \u0005[אצל]\u0006 איסור \u0003שביעית עבדינן מידי\u0004 \u0005[אנו\u0006 \u0003עושים דבר]\u0004 ש\u0003ודאי קשי\u0004 \u0005[קשה]\u0006 \u0003לה\u0004 כדי שוודאי לא תצמח יותר על ידי כך, \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003מקח וממכר עבדינן מידי\u0004 \u0005[אנו\u0006 \u0003עושים דבר]\u0004 ש\u0003ודאי מעלי\u0004 \u0005[מועיל]\u0006 \u0003לה,\u0004 שכך היא דעת המוכר, כדי שתחזור ותצמח.","ועוד שנינו בברייתא: \u0003בדקלים ובארזים חופר ומשרש, לפי שאין גזען מחליף.\u0004 ותוהים: \u0003ו\u0004כי \u0003ארז אין גזעו מחליף? והא דריש\u0004 \u0005[והרי דרש]\u0006 \u0003ר' חייא בר לולייני, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"צדיק כתמר יפרח כארז בלבנון ישגה\"\u0004 (תהלים צב, יג)? \u0003אם נאמר תמר למה נאמר ארז, ואם נאמר ארז, למה נאמר תמר?\u0004","ומסביר: \u0003אילו נאמר ארז ולא נאמר תמר, הייתי אומר: מה ארז אין עושה פירות, אף צדיק אין עושה פירות\u0004 ואין למעשיו שכר בעולם הבא, \u0003לכך נאמר תמר\u0004 שהוא עושה פירות.","\u0003ואם נאמר תמר ולא נאמר ארז, הייתי אומר: מה תמר אין גזעו מחליף, אף צדיק אין גזעו מחליף,\u0004 שאם מת \u0003לא יהיה בנו אחריו כמותו,\u0004 \u0003לכך נאמר ארז!\u0004","ומשיבים: \u0003אלא הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003בשאר מיני ארזים,\u0004 כלומר, לא במין מסויים זה שאין גזעו מחליף, אלא במינים אחרים. \u0003כ\u0004דברי \u0003רבה בר רב הונא:\u0004 ש\u0003אמר רבה בר רב הונא, אמרי בי\u0004 \u0005[אומרים בבית\u0006 מדרשו\u0005]\u0006 של \u0003רב: עשרה מיני ארזים הן, שנאמר: \"אתן במדבר ארז שטה והדס ועץ שמן אשים\u0004 בערבה ברוש תדהר ותאשור יחדיו\u0003\"\u0004 (ישעיה מא, יט), \u0003\"ארז\"\u0004 הוא הקרוי בארמית \u0003ארזא, \"שיטה\"\u0004 קרויה בארמית \u0003תורניתא, \"הדס\"\u0004 — \u0003אסא, \"עץ שמן\"\u0004 הוא \u0003אפרסמא\u0004 \u0005[אפרסמון],\u0006 \u0003\"ברוש\"\u0004 — \u0003ברתי, \"תדהר\"\u0004 הוא הקרוי בארמית \u0003שאגא, \"ותאשור\"\u0004 — \u0003שורבינא.\u0004","ושואלים: \u0003הני\u0004 \u0005[אלה]\u0006 \u0003שבעה הוי\u0004 \u0005[הם]\u0006 ולא עשרה! \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי אמר, הוסיפו עליהן\u0004 כמיני ארזים: \u0003אלונים, אלמונים, אלמוגים.\u0004 ומסבירים: \u0003אלונים\u0004 הם הקרויים בארמית \u0003בוטני, אלמונים\u0004 הם הקרויים \u0003בלוטי, אלמוגים\u0004 —"],["\u0003כסיתא\u0004 \u0005[אלמוגים].\u0006 \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שהאילנות הנוספים הם: \u0003ערונים, ערמונים, אלמוגים.\u0004 ומפרשים: \u0003ערונים\u0004 הם הקרויים \u0003ערי\u0004 (דפנה), \u0003ערמונים\u0004 הם הקרויים \u0003דולבי, אלמוגים\u0004 הם \u0003כסיתא.\u0004","\u0003הקונה שני אילנות בתוך שדה חבירו\u0004 — \u0003הרי זה לא קנה קרקע\u0004 שעמהן, אלא את האילנות בלבד. \u0003ר' מאיר אומר: קנה קרקע.\u0004 וחוזרים לדברי התנא הראשון. אם \u0003הגדילו\u0004 האילנות \u0003לא ישפה\u0004 בעל הקרקע, לא יקצוץ מהם ענפים אף על פי שצילם מזיק לשדהו. \u0003ו\u0004באשר לזכות בענפים היוצאים מן העץ, הרי \u0003העולה מן הגזע\u0004 — \u0003שלו,\u0004 של בעל האילן, אבל מה שיוצא \u0003מן השרשים\u0004 הוא \u0003של בעל הקרקע, ואם מתו\u0004 שני אילנות אלה — \u0003אין לו\u0004 לבעל האילנות \u0003קרקע\u0004 שעמדו עליה.","אם \u0003קנה שלשה\u0004 אילנות — \u0003קנה\u0004 גם \u0003קרקע.\u0004 במקרה זה, אם \u0003הגדילו\u0004 האילנות הללו \u0003ישפה\u0004 בעל הקרקע, משום שמכר לו קרקע מוגדרת יחד עימם ולא את כל שדהו. \u0003והעולה מן הגזע ו\u0004גם \u0003מן השרשין שלו\u0004 של הקונה, \u0003ואם מתו\u0004 האילנות \u0003יש לו קרקע\u0004 שנמכרה עימם.","\u0003תנן התם\u0004 \u0005[שנינו שם]:\u0006 \u0003הקונה שני אילנות בתוך\u0004 שדה \u0003של חבירו\u0004 — \u0003מביא\u0004 ביכורים מהם \u0003ואינו קורא,\u0004 משום שמאחר שאין הקרקע שלו אינו יכול לקרוא בכך את לשון וידוי הביכורים \"הבאתי את ראשית פרי האדמה אשר נתת לי\" (דברים כו, י). ואילו \u0003ר' מאיר אומר: מביא ו\u0004גם \u0003קורא.\u0004","\u0003אמר רב יהודה אמר שמואל: מחייב היה ר' מאיר\u0004 בביכורים \u0003אף בלוקח פירות מן השוק,\u0004 ולאו דווקא במי שגדלו הפירות על אילנות שלו. \u0003ממאי\u0004 \u0005[ממה]\u0006 הוא מסיק דבר זה? \u0003מדקתני\u0004 \u0005[ממה\u0006 \u0003ששנה]\u0004 \u0003משנה יתירא\u0004 שאינה נחוצה; \u0003מכדי תנא ליה\u0004 \u0005[הרי כבר שנוי לו,\u0006 לר' מאיר\u0005]\u0006 במשנתנו, ש\u0003יש לו קרקע\u0004 בין שתי האילנות, אם כן \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן \u0005מאליו\u0006\u0005]\u0006 ש\u0003מביא וקורא.\u0004","\u0003אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003מחייב היה ר' מאיר אף בלוקח פירות מן השוק,\u0004 שאף אם לענין קניינים היה הדין כדברי חכמים, שאין לו קרקע, מכל מקום הוא צריך להביא ביכורים.","ומקשים על אפשרות כזאת: \u0003והא כתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"אשר תביא מארצך\"\u0004 (דברים כו, ב), משמע: מקרקע שלך ולא של אחר! ומשיבים: \u0003ההוא\u0004 \u0005[אותו\u0006 כתוב\u0005]\u0006 \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003חוצה לארץ\u0004 הוא בא, שאיננה ארצך, ואין הכוונה למעט קרקע שאינה קניינו הפרטי.","ומקשים: \u0003והא כתיב\u0004 \u0005[והרי נאמר]:\u0006 \"ראשית ביכורי \u0003אדמתך\u0004 תביא\" (שמות כג יט)! ומשיבים: דבר זה בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003אדמת גוי\u0004 בארץ ישראל, שאם קנה פירות קרקע זו אינו מביא ביכורים. ומקשים: \u0003והכתיב\u0004 \u0005[והרי נאמר\u0006 כתוב נוסף\u0005]:\u0006 \u0003\"\u0004ועתה הנה הבאתי את ראשית פרי האדמה \u0003אשר נתתה לי\"\u0004 (דברים כו, י), ואם קונה מן השוק אין זה, לכאורה, מה שנתן לו ה'! ומשיבים: אף לשון \"אשר נתת לי\" ניתן לפרש כך: \u0003דיהבת\u0004 \u0005[שנתת]\u0006 \u0003לי זוזי וזבני בהו\u0004 \u0005[כספים וקניתי בהם]\u0006 פרי זה.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רבה\u0004 ממה ששנינו בברייתא: \u0003הקונה אילן אחד בתוך של חבירו\u0004 — \u0003מביא ואינו קורא, לפי שלא קנה קרקע,\u0004 אלו \u0003דברי ר' מאיר.\u0004 אם כן \u0003תיובתא\u0004 \u0005[קושיה\u0006 חמורה\u0005]\u0006 לשמואל, שאמר שלדעת ר' מאיר חייב בביכורים אף שקונה פירות בלבד.","ובענין זה של חובת ביכורים במי שקונה אילן בשדה חבירו \u0003אמר לו ר' שמעון בן אליקים לר' אלעזר:\u0004"],["\u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' מאיר באילן אחד\u0004 שמביא ביכורים ואינו קורא, \u0003ומאי טעמא דרבנן\u0004 \u0005[ומה הטעם של חכמים]\u0006 \u0003בשני אילנות\u0004 שמביא ואינו קורא? אם אין לו קרקע ואינו חייב משום כך בקריאה — משום מה מביא? ואם יש לו חיוב להביא — מפני מה אינו קורא? \u0003אמר לו\u0004 ר' אלעזר: \u0003דבר שהראשונים לא אמרו בו טעם, תשאלני בבית המדרש\u0004 בפומבי \u0003כדי לביישני?\u0004 כלומר, איני יודע, ודבר זה אף ראשונים לא נתנו בו טעם.","\u0003אמר רבה: מאי קושיא\u0004 \u0005[מה הקושי\u0006 בדבר\u0005]?\u0006 \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003ר' מאיר באילן אחד ספוקי מספקא ליה\u0004 \u0005[מסתפק הוא]\u0006 אם יש לו קרקע, \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 \u0003בשני אילנות ספוקי מספקא להו\u0004 \u0005[מסופק להם],\u0006 ומשום הספק הם אומרים שאינו יכול להפקיע את עצמו מן החיוב להביא, אבל אינו קורא כאשר אין ברור שהוא חייב בכך!","ומקשים: \u0003ומי מספקא ליה\u0004 \u0005[והאם מסופק לו]\u0006 דבר זה לר' מאיר? \u0003והא קתני\u0004 \u0005[והרי שנה]:\u0006 \u0003לפי שלא קנה קרקע,\u0004 אלו \u0003דברי ר' מאיר,\u0004 משמע שברור לו שלא קנה קרקע! ומשיבים: \u0003אימא\u0004 \u0005[אמור]\u0006 ותקן: \u0003שמא לא קנה קרקע.\u0004","ומקשים: אם כן, שמשום ספק הוא שמביא ביכורים, \u0003וליחוש דדלמא לאו\u0004 \u0005[ונחשוש שמא לא]\u0006 \u0003ביכורים נינהו\u0004 \u0005[הם],\u0006 \u0003וקא מעייל\u0004 \u0005[והוא מכניס]\u0006 \u0003חולין לעזרה\u0004 ואסור לעשות כן! ומשיבים: מדובר כאן באופן ש\u0003מקדיש להו\u0004 \u0005[אותם]\u0006 ואם כן שוב אינם חולין. ומקשים: \u0003והא בעי מיכלינהו\u0004 \u0005[והרי צריך\u0006 הכהן \u0005לאכול אותם]\u0006 כי הם ביכורים, ואם מוקדשים הם אינו יכול לאוכלם! ומשיבים: \u0003דפריק להו\u0004 \u0005[שפודה אותם].\u0006 ומקשים עוד: \u0003ודלמא לאו\u0004 \u0005[ושמא לא]\u0006 \u0003בכורים נינהו\u0004 \u0005[הם],\u0006 \u0003וקא מפקע להו\u0004 \u0005[והוא מפקיע אותם]\u0006 על ידי כך \u0003מתרומה ומעשר,\u0004 שהרי אין מפרישים תרומה ומעשר מפירות הביכורים! ומשיבים: מדובר כאן באופן ש\u0003מפריש להו\u0004 \u0005[להם,\u0006 מהם\u0005]\u0006 תרומה ומעשר מפני הספק.","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003תרומה גדולה\u0004 שמפריש מהם \u0003יהיב לה\u0004 \u0005[נותן אותה]\u0006 \u0003לכהן,\u0004 וממה נפשך יכול הוא לתת, שאם תרומה היא — הרי היא לכהן, ואם ביכורים הם הפירות — גם הם לכהן. \u0003מעשר שני נמי יהיב ליה\u0004 \u0005[גם כן נותן לו]\u0006 \u0003לכהן,\u0004 והכהן אוכל בירושלים, אם מדין מעשר ואם מדין ביכורים. וכיוצא בזה אם היה זה בשנה שלישית או שישית לשנות השמיטה, שצריך לתת \u0003מעשר עני\u0004 במקום מעשר שני — \u0003נמי יהיב ליה\u0004 \u0005[גם כן נותן אותו]\u0006 \u0003לכהן עני,\u0004 שאוכל את הפירות אם בתורת עני ואם בתורת ביכורים, \u0003אלא מעשר ראשון\u0004 הלא של \u0003לוי הוא, למאן יהיב ליה\u0004 \u0005[למי נותן אותו]?\u0006","ומשיבים: \u0003דיהיב ליה\u0004 \u0005[שנותן אותו]\u0006 \u0003לכהן,\u0004 \u0003כ\u0004דעת \u0003ר' אלעזר בן עזריה. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003תרומה גדולה\u0004 ניתנת \u0003לכהן, מעשר ראשון\u0004 ניתן \u0003ללוי,\u0004 ודווקא לאלו, אלו \u0003דברי ר' עקיבא. ר' אלעזר בן עזריה אומר: מעשר ראשון\u0004 ניתן \u0003אף לכהן.\u0004 ועוד שואלים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 \u0003בכורים נינהו\u0004 \u0005[הם]\u0006 \u0003ובעו קרייה\u0004 \u0005[ו\u0006הם \u0005צריכים קריאה]\u0006 והוא לא קרא! ומשיבים: \u0003קרייה לא מעכבת\u0004 את מצוות הבאת הביכורים.","ומקשים: \u0003ו\u0004האם \u0003לא? והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' זירא\u0004 לענין אחר: \u0003כל הראוי לבילה\u0004 (בלילה), אם הקדיש מנחה שכמות הסולת שבתוכה היא כזו שאפשר לבלול אותה בכמות השמן המיועדת למנחה אחת — \u0003אין בילה מעכבת בו,\u0004 שאף על פי שמצוה לכתחילה לבלול את כולה בשמן, אם לא בלל — אינו מעכב. \u0003ו\u0004אולם כל \u0003שאינו ראוי לבילה\u0004 שאם הסולת שבמנחה מרובה כל כך, עד שאי אפשר לבלול אותה — \u0003בילה מעכבת בו.\u0004 ואם כן, אף ביכורים אלה שאינם ראויים לקריאה — קריאה תהא מעכבת בהם, ולא יביאם כלל!","ומשיבים: \u0003דעביד להו\u0004 \u0005[שעושה בהם]\u0006 שייפטרו לגמרי מחובת הקריאה, \u0003כ\u0004דברי \u0003ר' יוסי בר חנינא,\u0004 ש\u0003אמר:\u0004 אם \u0003בצרן\u0004 את הביכורים \u0003ושגרן\u0004 (שלח אותן) \u0003ביד שליח, ומת\u0004 ה\u0003שליח בדרך\u0004 — \u0003מביא\u0004 הבעלים או אדם אחר את הביכורים \u0003ו\u0004אולם \u0003אינו קורא\u0004 עליהם, \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ולקחת... והבאת\"\u0004 (ראה דברים כו, ב–ג),"],["\u0003עד שתהא לקיחה והבאה כאחד, והא ליכא\u0004 \u0005[והרי אין כאן].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אויא לרב אשי:\u0004 מדוע צריך להגיע לפתרון כזה? \u0003מכדי פסוקי נינהו\u0004 \u0005[הלא פסוקים\u0006 הם \u0005אלה]\u0006 שהוא אומר בוידוי הביכורים, \u0003ליקרי\u0004 \u0005[שיקרא\u0006 אותם\u0005]\u0006 ומה הבעיה בקריאת פסוקים מן התורה?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003משום דמחזי כשיקרא\u0004 \u0005[שנראה\u0006 הדבר \u0005כשקר]\u0006 שאומר לפני ה' דברים שאינם אמת, שמא אין זו אדמתו. \u0003רב משרשיא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב חייא אמר:\u0004 יש כאן חשש אחר, \u0003דלמא אתי לאפקועינהו\u0004 \u0005[שמא יבוא להפקיעם]\u0006 \u0003מתרומה ומעשר\u0004 אם נוהג בהם ממש כמו בביכורים ודאיים, ומשום כך עושים בהם הבדל זה, שלא יקרא.","שנינו במשנה שהקונה שני אילנות בשדה חבירו, אם \u0003הגדילו\u0004 — \u0003לא ישפה.\u0004 ועוד נאמר שם שכל היוצא מן הגזע הרי הוא של בעל האילנות, והיוצא מן השורשים של בעל הקרקע. ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק]\u0006 \u0003מן הגזע, והיכי דמי\u0004 \u0005[וכיצד הוא בדיוק]\u0006 \u0003מן השרשין?\u0004","\u0003אמר ר' יוחנן: כל\u0004 אותו החלק \u0003שרואה פני חמה,\u0004 שנראה בגלוי מעל הקרקע — \u0003זהו\u0004 נקרא \u0003\"מן הגזע\", ושאינו רואה פני חמה\u0004 אלא טמון בקרקע — \u0003זהו \"מן השרשין\".\u0004","ושואלים: אם כל היוצא מן הגזע, ואפילו גבוה במעט מן הקרקע, של בעל האילנות הוא, \u0003וליחוש\u0004 \u0005[ושנחשוש]\u0006 \u0003דלמא מסקא ארעא\u0004 \u0005[שמא תעלה הארץ]\u0006 \u0003שירטון,\u0004 ששטף מים יביא לשם אדמה ותכסה מעט מן הגזע, ואותם ענפים היוצאים מן הגזע ייראו כאילו הם אילנות הצומחים לעצמם, \u0003ואמר ליה\u0004 \u0005[ויאמר לו]\u0006 בעל האילנות לבעל השדה: \u0003תלתא זבינת\u0004 \u0005[שלושה\u0006 אילנות \u0005מכרת]\u0006 \u0003לי ואית\u0004 \u0005[ויש]\u0006 \u0003לי ארעא\u0004 \u0005[קרקע]!\u0006 \u0003אלא אמר רב נחמן:\u0004 אמנם מה שיוצא מן הגזע שייך לבעל האילנות, ואולם בכל זאת \u0003יקוץ\u0004 (יקצוץ) אותו. \u0003וכן אמר ר' יוחנן\u0004 עצמו: \u0003יקוץ.\u0004","\u0003אמר רב נחמן, נקיטינן\u0004 \u0005[מוחזקים אנו]\u0006 מרבותינו הלכה זו: \u0003דקל\u0004 שקנה אדם מחבירו \u0003אין לו גזע. סבר\u0004 \u0005[סבור\u0006 היה\u0005]\u0006 \u0003רב זביד למימר\u0004 \u0005[לומר]\u0006 שהכוונה היא: \u0003אין לו גזע,\u0004 כלומר, מה שעולה מן הגזע \u0003לבעל דקל,\u0004 ומדוע? ש\u0003כיון דלמחפר\u0004 \u0005[שלחפור]\u0006 \u0003ולשרש קאי\u0004 \u0005[\u0006הוא \u0005עומד]\u0006 שאם ימות או ייקצץ הדקל שוב אין לו זכות ליטוע אילן במקומו — \u0003אסוחי מסח דעתיה\u0004 \u0005[מסיח\u0006 את \u0005דעתו\u0006 ממנו\u0005].\u0006","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב פפא: והא\u0004 \u0005[והרי]\u0006 \u0003קונה שני אילנות\u0004 בשדה חבירו, \u0003דלמחפר ולמשרש קיימי\u0004 \u0005[שלחפור ולשרש עומדים]\u0006 שהרי אם ימותו אינו רשאי לנטוע אחרים במקומם, \u0003וקתני\u0004 \u0005[ושנינו]\u0006 במשנתנו ש\u0003יש לו\u0004 מה שעולה מן ה\u0003גזע! אלא אמר רב פפא:\u0004 הכוונה היא ש\u0003אין לו גזע לבעל דקל,\u0004 ודווקא לבעל דקל, ולא לבעל אילן אחר — \u0003לפי שאין\u0004 דקל \u0003מוציא גזע,\u0004 כלומר, אינו מצמיח כלל ענפים מן הגזע.","ושואלים: \u0003ולרב זביד\u0004 שהבין כי רב נחמן מדבר על כל אילן, \u0003קשיא מתניתין\u0004 \u0005[קשה משנתנו]!\u0006 ומשיבים: רב זביד מפרש שהמשנה מדברת במקרה \u0003דזבין\u0004 \u0005[שקנה]\u0006 את המקום \u0003לחמש שנין\u0004 \u0005[שנים]\u0006 והתנה שיש לו בשנים אלה זכות אף לנטוע אחר במקומו.","שנינו במשנה שאם \u0003קנה שלשה\u0004 אילנות — \u0003קנה קרקע.\u0004 ושואלים: \u0003וכמה\u0004 קרקע קנה? \u0003אמר ר' חייא בר אבא אמר ר' יוחנן: הרי זה קנה\u0004 את הקרקע ש\u0003תחתיהן,\u0004 תחת האילנות ממש, \u0003ו\u0004את השטח ש\u0003ביניהן,\u0004 בין האילנות, \u0003ו\u0004גם את השטח ש\u0003חוצה להן\u0004 מחוץ לאילנות וענפיהם,"],["\u0003כמלוא אורה\u0004 (לוקט תאנים) שעומד סמוך לעץ \u0003וסלו\u0004 בידו. \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' אלעזר: השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 יודעים אנו ש\u0003דרך אין לו,\u0004 והוא צריך לקנות לעצמו דרך לאילנות שקנה, שטח כדי \u0003אורה וסלו יש לו?\u0004 ומסבירים דבריו: \u0003דרך אין לו,\u0004 למרות שאין לו אפשרות אחרת להגיע אליהם, משום \u0003דארעא אחריתי\u0004 \u0005[שקרקע אחרת]\u0006 \u0003היא\u0004 הקרקע שקנה עם האילנות, ואינה חלק מן השדה, מקום \u0003אורה וסלו יש לו?!\u0004","\u0003אמר ר' זירא, מדברי רבינו,\u0004 ר' אלעזר, ומקושייתו \u0003נלמד\u0004 כי הקונה \u0003שלשה\u0004 אילנות — \u0003הוא\u0004 ש\u0003אין לו דרך,\u0004 משום שבגלל האילנות קנה לו גם קרקע משל עצמו, \u0003הא\u0004 \u0005[הרי]\u0006 הקונה \u0003שנים\u0004 — \u0003יש לו,\u0004 \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 קונה האילנות: \u0003בארעא דידך קיימי\u0004 \u0005[באדמה שלך\u0006 הם \u0005עומדים],\u0006 וכיון שיש לי רשות להשתמש בקרקע לצורך האילנות, רשאי אני גם כן לעבור בקרקע שלך.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן בר יצחק לרבא: לימא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 ש\u0003ר' אלעזר לית ליה\u0004 \u0005[אין לו,\u0006 אינו מקבל\u0005]\u0006 את שיטת \u0003שמואל רביה\u0004 \u0005[רבו],\u0006 שהיה רבו של ר' אלעזר בבבל, ש\u0003אמר שמואל: הלכה כ\u0004שיטת \u0003ר' עקיבא,\u0004 ש\u0003אמר: מוכר בעין יפה מוכר?\u0004 שהרי לשיטת ר' עקיבא, המוכר לחבירו דבר שברשותו מקנה לו גם זכות מעבר לאותו דבר!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 אף אם ר' אלעזר עצמו סבור כדעת ר' עקיבא \u0003לא מתוקמא מתניתין\u0004 \u0005[אין משנתנו\u0006 יכולה להיות \u0005מועמדת,\u0006 מוסברת\u0005]\u0006 \u0003כ\u0004דעת \u0003ר' עקיבא,\u0004 אלא כדברי חכמים הסבורים שהמוכר בעין רעה מוכר, ולשיטתם הקשה ר' אלעזר על דברי ר' יוחנן.","\u0003ממאי\u0004 \u0005[ממה]\u0006 הוא לומד זאת? \u0003מדקתני\u0004 \u0005[ממה ששנה]\u0006 במשנה: אם \u0003הגדילו\u0004 שלושת האילנות שמכר — \u0003ישפה\u0004 יקצוץ בעל השדה את הענפים שגדלו מעבר לתחום, \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 שלשיטת \u0003ר' עקיבא היא, אמאי\u0004 \u0005[מדוע]\u0006 \u0003ישפה? האמר\u0004 \u0005[הרי אמר]:\u0006 \u0003מוכר בעין יפה מוכר!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: מכאן אין ראיה, שכן \u0003אימור\u0004 \u0005[אמור]\u0006 ש\u0003אמר ר' עקיבא\u0004 — \u0003גבי\u0004 \u0005[אצל]\u0006 הקונה \u0003בור ודות\u0004 בשדה חבירו, שיש לו זכות מעבר אליהם \u0003דלא מכחשי ארעא\u0004 \u0005[שאינם מכחישים,\u0006 מפסידים, \u0005את הקרקע],\u0006 ואין הפסד נמשך מכאן למוכר, ואולם \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003אילן\u0004 שגורם הפסד לשדה \u0003מי\u0004 \u0005[האם]\u0006 \u0003שמעת ליה\u0004 \u0005[אותו]\u0006 אומר שהמוכר מקבל על עצמו דבר שכזה?","\u0003מי\u0004 \u0005[האם]\u0006 \u0003לא מודי\u0004 \u0005[מודה]\u0006 \u0003ר' עקיבא באילן הנוטה לתוך שדה חבירו, שקוצץ\u0004 חבירו בעל השדה את ענפי האילן \u0003מלא\u0004 גובה הנפה של \u0003מרדע מעל גבי מחרישה?\u0004 שכיון שענפים בעץ של חבירו מפריעים לו לחרוש בשדהו — רשאי לקצוץ. משמע שאף לדעת ר' עקיבא אינו נותן משלו במקום שנגרם לו נזק. ולפיכך אפשר לפרש את משנתנו כדברי ר' עקיבא, וצריך לומר שר' אלעזר אינו סבור כמותו.","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' חייא בר אבא\u0004 בשם ר' יוחנן: הקונה שלושה אילנות בתוך של חבירו \u0003הרי זה קנה תחתיהן, וביניהן, וחוצה להן כמלוא אורה וסלו.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: אותן\u0004 אמות שהן כדי \u0003אורה וסלו\u0004 מסביב לאילנות, שמשתמשים בהן רק בזמנים מסויימים, \u0003מי זורען\u0004 בשאר ימות השנה, בעל השדה או בעל האילנות? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003תניתוה\u0004 \u0005[שניתם אותה]\u0006 במשנה: מי שהיתה לו גינה לפנים מגינתו של חבירו, יש לו זכות לדרך לעבור אל גינתו, ואף על פי כן \u0003החיצון זורע את הדרך.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003מי דמי\u0004 \u0005[האם דומים\u0006 הדברים\u0005]?\u0006 \u0003התם לית ליה פסידא\u0004 \u0005[שם אין לו הפסד]\u0006 \u0003ללוקח\u0004 כשהחיצון זורע את הדרך, שהרי הוא יכול לעבור בה, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 \u0003אית ליה פסידא\u0004 \u0005[יש לו הפסד]\u0006 \u0003ללוקח, דאמר ליה\u0004 \u0005[שאומר לו]\u0006 לוקח האילנות: \u0003קמיטנפי פירי\u0004 \u0005[מתלכלכים הפירות]\u0006 הנופלים מן האילנות מחמת הזרעים.","\u0003הא לא דמיא\u0004 \u0005[אין זה דומה]\u0006 \u0003אלא לסיפא\u0004 \u0005[לסופה]\u0006 של אותה משנה, ששנינו בה: אם הדרך לגינה הפנימית עוברת לא ישירות, אלא מן הצד, כך שיש בכך הפסד מסויים גם לפנימי, שאינו מגיע בדרך הקצרה לגינתו, \u0003ו\u0004על כך נאמר ש\u0003זה וזה,\u0004 החיצון והפנימי, \u0003אינן רשאין לזורעה.\u0004 ואף כאן, לא בעל השדה ולא בעל האילנות רשאים לזרוע במקום אורה וסלו.","ומעירים, \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003אביי: הרי זה קנה תחתיהן וביניהן וחוצה להן כמלוא אורה וסלו, וזה וזה אינן רשאין לזורעה.\u0004","הלכה למעשה שואלים: \u0003וכמה יהא ביניהן\u0004 בין העצים, שייחשבו שלושה אילנות כיחידה אחת שזוכה הקונה בקרקע שביניהם? \u0003רב יוסף אמר\u0004 בשם \u0003רב יהודה\u0004 ש\u0003אמר\u0004 בשם \u0003שמואל:\u0004 אם היו מרוחקים זה מזה \u0003מארבע אמות ועד שמונה. רבא אמר\u0004 בשם \u0003רב נחמן\u0004 ש\u0003אמר\u0004 בשם \u0003שמואל: משמונה\u0004 אמות \u0003ועד שש עשרה. אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: לא תפלוג עליה\u0004 \u0005[תחלוק עליו]\u0006 על \u0003רב נחמן, דתנן מתניתין כוותיה\u0004 \u0005[ששנינו במשנתנו כשיטתו],\u0006","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003הנוטע את כרמו שש עשרה אמה על שש עשרה אמה,\u0004 שיש שש עשרה אמה בין שורת גפנים לחבירתה — \u0003מותר להביא זרע לשם\u0004 למקום הפנוי בין השורות, ואין זה נחשב כזורע בכרם שעובר על איסור כלאים.","\u0003אמר ר' יהודה: מעשה\u0004 היה \u0003ב\u0004עיר \u0003צלמון, באחד שנטע את כרמו שש עשרה על שש עשרה אמה, והיה הופך שער\u0004 (ענפי) \u0003שתי שורות\u0004 שזו מול זו \u0003לצד אחד,\u0004 כלומר, זו לעבר זו, \u0003וזורע את הניר\u0004 את השטח שנתפנה בצידן האחר של השורות, \u0003לשנה אחרת היה הופך את השער למקום הזרע\u0004 של השנה שעברה \u0003וזרע את הבור,\u0004 כלומר, מה שהיה בשנה שעברה שטח לא זרוע, ששם היו הגפנים, \u0003ובא מעשה לפני חכמים והתירוהו.\u0004 משמע שאם אילנות מרוחקים זה מזה יותר משש עשרה אמות אינם נחשבים עוד כיחידה אחת.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 רב יוסף: \u0003אנא לא ידענא\u0004 \u0005[אני איני יודע],\u0006 \u0003אלא עובדא הוה\u0004 \u0005[מעשה היה]\u0006 של מכירת אילנות"],["\u0003בדורא דרעותא\u0004 \u0005[בכפר של רועים]\u0006 במעשה כגון זה, \u0003ואתו לקמיה\u0004 \u0005[ובאו לפני]\u0006 \u0003רב יהודה, ואמר ליה\u0004 \u0005[לו]\u0006 למוכר: \u0003\"זיל הב ליה\u0004 \u0005[לך תן לו]\u0006 קרקע לקונה האילנות, \u0003כמלא בקר וכליו\", ולא הוה ידענא\u0004 \u0005[הייתי יודע]\u0006 \u0003\"כמלא בקר וכליו\" כמה\u0004 הוא, \u0003כיון דשמעתה להא דתנן\u0004 \u0005[ששמעתי את זו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003לא יטע אדם אילן סמוך לשדה חבירו אלא אם כן הרחיק ממנה ארבע אמות,\u0004","\u0003ותני עלה\u0004 \u0005[ושנו עליה]\u0006 בברייתא: \u0003ארבע אמות שאמרו\u0004 — \u0003כדי עבודת הכרם, אמינא\u0004 \u0005[אמרתי]:\u0006 \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003\"כמלא בקר וכליו\"\u0004 הוא \u0003ארבע אמות.\u0004 ועד כאן שמענו כי לרב נחמן יש משנה המסייעתו, ואילו לרב יוסף — מעשה של רב יהודה.","ושואלים: \u0003וכרב יוסף מי\u0004 \u0005[האם]\u0006 \u0003לא תנן\u0004 \u0005[האם לא שנינו\u0006 במשנה\u0005]?\u0006 שהרי באותה משנה נאמר ש\u0003ר' מאיר ור' שמעון אומרים: הנוטע את כרמו שמונה אמות על שמונה\u0004 — \u0003מותר להביא זרע לשם,\u0004 משמע שיש מי שאומר שרווח של שמונה אמות גורם לכך שאין האילנות נחשבים ככרם או כשדה אילן!","ואומרים: \u0003אפילו הכי\u0004 \u0005[כך]\u0006 \u0003מעשה עדיף,\u0004 שהרי לשיטת רב נחמן יש ראיה ממעשה שהיה בצלמון, שנהגו בפועל כשיטתו.","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003לרב יוסף\u0004 שהולך \u0003אליבא\u0004 \u0005[לפי שיטתו]\u0006 של \u0003ר' שמעון, שמעינן ליה\u0004 \u0005[שומעים אנו אותו]\u0006 את ר' שמעון שאומר דין ב\u0003מפוזרין\u0004 מהו המרחק הגדול מדי, \u0003ושמעינן ליה\u0004 \u0005[ושומעים אנו אותו]\u0006 במה שאמר ב\u0003רצופין,\u0004 כלומר, מהו נחשב צפוף מדי; \u0003מפוזרין\u0004 — \u0003הא דאמרן\u0004 \u0005[זה שאמרנו],\u0006 \u0003רצופין\u0004 — מה הם? \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003כרם הנטוע על פחות מארבע אמות\u0004 — \u0003אינו כרם,\u0004 מפני שהאילנות צפופים יותר מדי, אלו \u0003דברי ר' שמעון, וחכמים אומרים:\u0004 גם זה \u0003כרם\u0004 הוא, אבל \u0003רואין את האמצעיים כאילו אינן\u0004 מפני שעתיד לעוקרם לאחר זמן מה.","\u0003אלא לרב נחמן אליבא דרבנן\u0004 \u0005[לפי שיטת חכמים],\u0006 \u0003מפוזרין שמעינן ליה\u0004 \u0005[שמענו אותו],\u0006 ממעשה של צלמון, דהיינו משש עשרה אמות ומעלה. אבל לגבי \u0003רצופין מי שמעינן ליה\u0004 \u0005[האם שמענו אותו]?\u0006 ואומרים: \u0003סברא הוא\u0004 שיש בדבר: \u0003מ\u0004כיון ש\u0003ל\u0004דעת \u0003ר' שמעון\u0004 שיעור הצפיפות הוא \u0003פלגא\u0004 \u0005[מחצית]\u0006 משיעור הפיזור, \u0003לרבנן נמי פלגא\u0004 \u0005[לחכמים גם כן\u0006 השיעור הוא \u0005מחצית],\u0006 ואם מפוזרים עד ששה עשר, צפופים הם בשמונה.","\u0003אמר רבא, הלכתא\u0004 \u0005[הלכה\u0006 היא\u0005]\u0006 בענין קונה שלושה אילנות, שיש לו קרקע אם הרווח ביניהם הוא \u0003מארבע אמות ועד שש עשרה\u0004 שמצרפים את שתי השיטות לטובת הקונה. \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רבא: כמה יהו מקורבין?\u0004 \u0003ארבע אמות, וכמה יהו מרוחקין? שש עשרה,\u0004 אם קנה שלושה אילנות —","\u0003הרי זה קנה קרקע ואת האילנות\u0004 הקטנים \u0003שביניהן, לפיכך\u0004 אם \u0003יבש האילן או נקצץ\u0004 — \u0003יש לו קרקע.\u0004 היו האילנות שקנה \u0003פחות מכאן,\u0004 שהם צפופים יותר, \u0003או יתר על כאן, או שלקחן בזה אחר זה\u0004 ולא קנה שלושה כאחד — \u0003הרי זה לא קנה לא את הקרקע ולא את האילנות שביניהן, לפיכך\u0004 אם \u0003יבש האילן או נקצץ\u0004 — \u0003אין לו קרקע.\u0004","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ירמיה: כשהוא מודד\u0004 את המרחק בין האילנות, האם \u0003ממקום קצר\u0004 (צר) שבגזע האילן \u0003הוא מודד, או ממקום רחב הוא מודד? אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב גביהה מבי כתיל לרב אשי: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר, ממה \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003הרכובה\u0004 (הענף הכפוף) \u0003שבגפן\u0004 — שבא למדוד ממנו לגפן שניה \u0003אינו מודד אלא מעיקר השני,\u0004 מהפקק השני שבגפנים, שהוא לא הרחב ביותר אלא ממוצע.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ירמיה:\u0004 אם \u0003מכר לו שלשה בדי אילן,\u0004 כלומר, שלושה ענפים שצמחו מאילן אחד, וכיסתה הקרקע את הגזע המשותף והריהם נראים כשלושה, \u0003מהו?\u0004 האם נחשבים הם כשלושה אילנות לקנות קרקע שביניהם?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב גביהה מבי כתיל לרב אשי: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003המבריך שלש גפנים\u0004 שמכסה זמורות של הגפנים באדמה על מנת שתשתרשנה שם ותצמחנה מהן גפנים חדשות, \u0003ועקריהן,\u0004 כלומר, החלק העולה מן האדמה \u0003נראין\u0004 — \u0003ר' אלעזר בר' צדוק אומר: אם יש ביניהן,\u0004 בין העיקרים והגפנים המוברכות \u0003מארבע אמות ועד שמונה\u0004 — \u0003מצטרפין\u0004 כולן להיחשב כרם של שש גפנים, \u0003ואם לאו\u0004 — \u0003אין מצטרפין.\u0004 משמע שבדים אף שהם מחוברים זה לזה, אם הם מכוסים נחשבים כל אחד לעצמו, ובלבד שיהו במרחק הראוי זה מזה.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב פפא: מכר לו שנים בתוך שדהו ואחד\u0004 עומד \u0003על המצר\u0004 (הגבול בין השדות), \u0003מהו?\u0004 וכן קנה \u0003שנים בתוך שלו ו\u0004עוד \u0003אחד בתוך של חבירו, מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006 האם מצטרפים אלה לשלושה, או לא? שאלה זו לא נפתרה ולכן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה."],["\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אשי: בור\u0004 מים שבין האילנות \u0003מהו שתפסיק\u0004 לענין זה של קניית הקרקע שביניהם? וכן \u0003אמת המים מהו שתפסיק? רשות הרבים מהו? ריכבא דדיקלי\u0004 \u0005[שורה של דקלים]\u0006 \u0003מהו?\u0004 לכל אחת מן השאלות הללו לא נמצאה תשובה ולכן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003הלל מרבי:\u0004 אם \u0003עלה ארז ביניהן\u0004 בין שלושת האילנות שקנה, \u0003מהו?\u0004 ותוהים: אם \u0003עלה\u0004 הלא \u0003ברשותא דידיה נפק\u0004 \u0005[ברשותו שלו יצא],\u0006 שהרי הקרקע שבין האילנות שלו היא, והארז שלו הוא! \u0003אלא\u0004 כך צריך לשאול: אם כשקנה שלושה אילנות \u0003היה ארז ביניהן, מהו?\u0004 האם עושה הוא הפסק בין האילנות? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003קנה וקנה,\u0004 כלומר, כיון שקנה את האילנות, קנה אף את מה שביניהם.","ועוד בענין זה נשאלה השאלה: \u0003כיצד הן עומדים\u0004 שלושה אילנות אלה כדי שתיקנה הקרקע שביניהם? \u0003רב אמר:\u0004 שעומדים \u0003כשורה\u0004 אחת, זה אחר זה, \u0003ושמואל אמר: כחצובא,\u0004 כמשולש. ומעירים: \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003כשורה, כל שכן\u0004 כשעומדים \u0003כחצובא\u0004 שקונה קרקע, \u0003ומאן דאמר\u0004 \u0005[ו\u0006אולם \u0005מי שאומר]\u0006 \u0003כחצובא, אבל כשורה\u0004 — \u0003לא,\u0004 אין הקרקע שביניהם מכורה לקונה, \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003משום דמיזדרע בינתייהו\u0004 \u0005[שנזרע,\u0006 שניתן לזרוע, \u0005ביניהם]\u0006 והמוכר אינו מוותר על שטח זה.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב המנונא: ולמאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר]\u0006 \u0003כחצובא, מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? שהקרקע נקנית? רק משום \u0003דלא מיזדרע בינתייהו\u0004 \u0005[שאין\u0006 אפשרות \u0005לזרוע ביניהם]?\u0006 \u0003אלא מעתה,\u0004 אם \u0003זבין ליה תלת היגי רומייתא\u0004 \u0005[מכר לו שלושה שיחים קוצניים רומיים]\u0006 \u0003דלא מיזדרע בינתייהו\u0004 \u0005[ש\u0006גם כן \u0005אין נזרע ביניהם],\u0006 \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר ש\u0003יש לו קרקע?! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הנך\u0004 \u0005[אלה]\u0006 \u0003לא חשיבי\u0004 \u0005[נחשבים],\u0006 שהם שיחים פחותים ואינם נחשבים לאילנות, ומשום כך אין הקרקע נקנית עימהם. אבל \u0003הנך חשיבי\u0004 \u0005[אלה\u0006 אילנות פרי \u0005חשובים\u0006 הם\u0005].\u0006","\u0003המוכר ראש בהמה גסה\u0004 — \u0003לא מכר את הרגלים\u0004 הקדמיות עימו, שכל אחד מהם חשוב לעצמו. וכל שכן אם \u0003מכר את הרגלים\u0004 — \u0003לא מכר את הראש.\u0004 וכן אם \u0003מכר את הקנה\u0004 — \u0003לא מכר את הכבד,\u0004 אף על פי שפעמים שהם מחוברים זה בזה, וכן \u0003מכר את הכבד\u0004 — \u0003לא מכר את הקנה. אבל ב\u0004בהמה \u0003דקה\u0004 שהיא קטנה, ואין כל חלק ממנה חשוב כל כך, אם \u0003מכר את הראש\u0004 — \u0003מכר את הרגלים\u0004 הקדמיות עימה, אבל אם \u0003מכר את הרגלים\u0004 — \u0003לא מכר את הראש, מכר את הקנה\u0004 — \u0003מכר את הכבד.\u0004 אבל אם \u0003מכר את הכבד\u0004 — \u0003לא מכר את הקנה\u0004 עימו.","ענין אחר, \u0003ארבע מדות במוכרין,\u0004 כלומר, במכירה: אם \u0003מכר לו חטין\u0004 ואמר שהן \u0003יפות ונמצאו\u0004 החיטים \u0003רעות\u0004 — \u0003הלוקח יכול לחזור בו\u0004 ולא המוכר; מכר לו \u0003רעות ונמצאו יפות\u0004 — ה\u0003מוכר יכול לחזור בו\u0004 ולא הלוקח; \u0003רעות ונמצאו רעות, יפות ונמצאו יפות\u0004 — \u0003אין אחד מהם יכול לחזור בו,\u0004 שהרי התקיים תנאי המכירה.","אם מכר לו \u0003שחמתית\u0004 (חומה, אדמדמה) \u0003ונמצאת לבנה,\u0004 או \u0003לבנה ונמצאת שחמתית,\u0004 וכן אם מכר לו \u0003עצים של זית ונמצאו של שקמה,\u0004 או מכר לו עצים \u0003של שקמה ונמצאו של זית,\u0004 או שמכר לו \u0003יין ונמצא חומץ,\u0004 וכן אם מכר לו \u0003חומץ ונמצא יין,\u0004 בכל אלה שלא מכר לו מה שהתנה, אף על פי שאין בכך טעות במחיר, מכל מקום כיון שלא על זה היה המכר — \u0003שניהם יכולין לחזור בהן.\u0004","\u0003אמר רב חסדא: מכר לו\u0004 אדם לחבירו, דבר שערכו היה \u0003שוה חמש בשש, והוקר\u0004 (התייקר) החפץ \u0003ועמד\u0004 עכשיו מחירו \u0003על שמנה,\u0004 והמוכר רוצה להחזיר את הכסף ולבטל את המיקח, משום שעכשיו עלה המחיר, \u0003מי נתאנה\u0004 (רומה) במיקח? — \u0003לוקח\u0004 (הקונה), שהרי המוכר מכר לו בתחילה ביותר מן המחיר הראוי. ולכן ה\u0003לוקח יכול לחזור בו,\u0004 אבל \u0003לא\u0004 ה\u0003מוכר,\u0004 ואף על פי שבסופו של דבר הוא מפסיד יותר. וטעמו של דבר — \u0003משום\u0004"],["\u0003דאמר ליה\u0004 \u0005[שיכול לומר לו]\u0006 הלוקח למוכר: \u0003אילו לא אוניתן\u0004 \u0005[היית מרמה אותי]\u0006 \u0003לא הוה מצית הדרת\u0004 \u0005[היית יכול לחזור]\u0006 \u0003בך\u0004 והיה המיקח מתקיים, וכל הרווח שלי הוא, \u0003השתא דאוניתן מצית הדרת\u0004 \u0005[עכשיו שרימית אותי יכול אתה לחזור]\u0006 \u0003בך\u0004 ולהרויח? \u0003ותנא תונא\u0004 \u0005[\u0006\u0005ו\u0006כן \u0005שנה התנא שלנו]\u0006 שאם התנה עמו למכור לו חיטים \u0003יפות ונמצאו רעות\u0004 — \u0003לוקח יכול לחזור בו ולא מוכר,\u0004 וממה שנאמרו הדברים בדרך פסוקה, משמע שאף אם ירצה המוכר לחזור (כגון כשעלה המחיר הרבה) — אינו יכול לחזור בו כלל.","\u0003ו\u0004כיוצא בזה \u0003אמר רב חסדא: מכר לו שוה שש בחמש, והוזלו ו\u0004בסוף \u0003עמדו על שלש, מי נתאנה\u0004 \u0005[רומה]\u0006 במקרה זה? — \u0003מוכר,\u0004 ולכן במקרה זה \u0003מוכר יכול לחזור בו ולא לוקח, דאמר ליה\u0004 \u0005[ש\u0006יכול \u0005לומר לו\u0006 המוכר\u0005]:\u0006 \u0003אילו לא אוניתן\u0004 \u0005[היית מרמה אותי]\u0006 \u0003לא הוה מצית הדרת\u0004 \u0005[היית יכול לחזור]\u0006 \u0003בך,\u0004 \u0003השתא מצית הדרת\u0004 \u0005[עכשיו יכול אתה לחזור]\u0006 \u0003בך?\u0004 \u0003ותנא תונא\u0004 \u0005[ו\u0006כן \u0005שנה התנא שלנו]\u0006 שאם התנה עמו למכור לו חיטים \u0003רעות ונמצאו יפות\u0004 — \u0003מוכר יכול לחזור בו ולא לוקח.\u0004","ותוהים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו בכך]\u0006 רב חסדא? הלא \u0003מתניתין היא\u0004 \u0005[משנתנו היא]\u0006 שבדברי המשנה הכלליים נכללים גם דברי רב חסדא! ומשיבים: \u0003אי ממתניתין\u0004 \u0003הוה אמינא\u0004 \u0005[אם ממשנתנו הייתי אומר]:\u0006 \u0003דלמא\u0004 \u0005[שמא]\u0006 במקרה שאמר \u0003רב חסדא\u0004 — \u0003תרוייהו מצו הדרי בהו\u0004 \u0005[שניהם יכולים לחזור בהם],\u0006 משום שהיתה שם אונאה בוודאי, שהחפץ נמכר ביותר מערכו, וכל עוד יכול הלוקח לחזור בו — לא נגמרה לגמרי העסקה, ומאחר שהמוכר גם הוא נתאנה — יכול אף הוא לחזור בו. \u0003ומתניתין הא אתא לאשמועינן\u0004 \u0005[ומשנתנו,\u0006 דבר \u0005זה באה להשמיע לנו]\u0006 שגם במקרה כזה, של שינוי מחיטים יפות לרעות — הרי זו אונאה וה\u0003לוקח יכול לחזור בו.\u0004","והוצרך לומר זאת \u0003דסלקא דעתך אמינא\u0004 \u0005[ש\u0006כן \u0005יעלה על דעתך לומר]\u0006 שאין זו בכלל אונאה, \u0003משום דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"רע רע יאמר\u0004 \u0003הקונה\u0004 ואוזל לו אז יתהלל\u0003\"\u0004 (משלי כ, יד), שדרך הקונים והמוכרים לגנות ולשבח את סחורתם, ועל כן השמיע לנו שיכול הלוקח לחזור בו אם נמצאו רעות (וכן המוכר אם נמצאו יפות).","שנינו במשנה שאם התנה למכור לו חיטה \u0003שחמתית ונמצאת לבנה\u0004 — שניהם יכולים לחזור. ומניחים ש\"שחמתית\" משמעו — שיש לה צבע כצבע החמה. ולפיכך \u0003אמר רב פפא: מדקתני\u0004 \u0005[ממה ששנה]\u0006 \u0003לבנה,\u0004 והמין השני של חיטים הידוע לנו הוא אדום, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003האי שמשא סומקתי\u0004 \u0005[שזו השמש אדומה]\u0006 \u0003היא\u0004 ולא לבנה. \u0003תדע\u0004 שכך הוא, \u0003דקא סמקא צפרא ופניא\u0004 \u0005[שהריהי מאדימה בבוקר ובערב].\u0006 \u0003והאי\u0004 \u0005[וזה]\u0006 ש\u0003לא קא חזינן כוליה יומא\u0004 \u0005[רואים\u0006 את הצבע האדום \u0005כל היום]\u0006 — \u0003נהורין\u0004 \u0005[מאור\u0006 עינינו\u0005]\u0006 \u0003הוא\u0004 ש\u0003לא ברי\u0004 \u0005[ברור],\u0006 ובגלל ריבוי האור איננו מבחינים בצבע האדום.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]:\u0006 והרי על הכתוב בדיני נגע הצרעת \u0003\"ומראהו עמק מן העור\"\u0004 (ויקרא יג, ל) אמרו חכמים שהכוונה היא: \u0003כמראה חמה\u0004 שהיא נראית \u0003עמוקה מן הצל, והתם\u0004 \u0005[ו\u0006הרי \u0005שם]\u0006 הנגע \u0003לבן הוא!\u0004 ומשיבים: הכוונה שם היא \u0003כמראה חמה, ו\u0004אולם \u0003לא כמראה חמה\u0004 בדיוק; \u0003כמראה חמה\u0004 — ש\u0003עמוקה מן הצל, ולא כמראה חמה\u0004 — ש\u0003אילו התם\u0004 \u0005[שם\u0006 בנגע\u0005]\u0006 צבעו \u0003לבן, והכא\u0004 \u0005[וכאן\u0006 בשמש\u0005]\u0006 צבעה \u0003אדום.\u0004","ושואלים: \u0003ולמאי דסליק דעתין מעיקרא\u0004 \u0005[ולמה שעלה\u0006 על \u0005דעתנו מתחילה]\u0006 שהשמש לבנה היא, \u0003הא קא סמקא צפרא ופניא\u0004 \u0005[הרי היא מאדימה בבוקר ובערב]!\u0006 ומשיבים: \u0003בצפרא\u0004 \u0005[בבוקר]\u0006 היא מאדימה משום \u0003דחלפא אבי וורדי\u0004 \u0005[שהיא עוברת על פני חלקת הוורדים]\u0006 של \u0003גן עדן\u0004 ומהשתקפותם נעשה האור אדום, \u0003בפניא\u0004 \u0005[בערב]\u0006 היא מאדימה משום \u0003דחלפא אפתחא\u0004 \u0005[ש\u0006היא \u0005חולפת על פתחו]\u0006 של \u0003גיהנם\u0004 ומכוח האש היא נראית אדומה. \u0003ואיכא דאמרי איפכא\u0004 \u0005[ויש שאומרים להיפך]\u0006 לגבי סיבת האדמימות בבוקר ובערב.","שנינו במשנה שאם שאם התנה עמו למכור לו \u0003יין ונמצא חומץ\u0004 — \u0003שניהן,\u0004 המוכר והקונה, \u0003יכולין לחזור בהן.\u0004 ומציעים: \u0003לימא, מתניתין\u0004 \u0005[האם\u0006 \u0003לומר\u0004 ש\u0003משנתנו]\u0004 כשיטת \u0003רבי היא ולא\u0004 כשיטת \u0003רבנן\u0004 \u0005[חכמים]?\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006"],["\u0003יין וחומץ מין אחד הוא,\u0004 כגון שאם תרם מזה על זה — תרומתו תרומה. \u0003רבי אומר: שני מינין\u0004 הם, ולכאורה משנתנו היא שלא כדעת חכמים! ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהיא כשיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 משום ש\u0003עד כאן לא פליגי רבנן עליה\u0004 \u0005[נחלקו חכמים עליו]\u0006 על \u0003רבי אלא לענין מעשר ותרומה\u0004 אם מפרישים מזה על זה. \u0003וכ\u0004דברי \u0003ר' אלעא,\u0004 ש","\u0003אמר ר' אלעא: מנין לתורם\u0004 באותו מין עצמו \u0003מן הרעה,\u0004 דבר שאינו משובח, או מקולקל קצת, \u0003על היפה, שתרומתו תרומה\u0004 למרות שלא עשה כדין? \u0003שנאמר: \"ולא תשאו עליו חטא בהרימכם את חלבו ממנו\u0004 ואת קדשי בני ישראל לא תחללו ולא תמותו","\u0003\"\u0004(במדבר יח, לב), ופסוק זה מתפרש: לא תחטאו אם תפרישו כתרומה (\"תרימו\") את החלק המובחר (\"חלבו\"). ומכאן שאם מפריש דבר שאינו מובחר — חוטא בכך. אבל מכתוב זה אפשר גם ללמוד שהתרומה אפילו מן הרע על היפה נתקדשה, כי \u0003אם אינו קדוש\u0004 על ידי תרומה שכזו \u0003נשיאות חטא למה?\u0004 הרי לא נעשה מעשה כלל! \u0003מכאן לתורם מן הרעה על היפה שתרומתו תרומה;\u0004 וכלפי דבר זה אמרו חכמים שהמפריש חומץ על יין — מכל מקום יצא, משום שבאמת מין אחד הוא.","\u0003אבל לענין מקח וממכר, דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 ואף לדעת חכמים שני מינים הם, כיון ש\u0003איכא דניחא ליה בחמרא\u0004 \u0005[יש\u0006 אדם \u0005שנוח לו ביין]\u0006 \u0003ולא ניחא ליה בחלא\u0004 \u0005[נוח לו בחומץ],\u0006 \u0003ואיכא דניחא ליה בחלא\u0004 \u0005[ויש\u0006 אדם \u0005שנוח לו\u0006 \u0003בחומץ]\u0004 \u0003ולא ניחא ליה בחמרא\u0004 \u0005[נוח לו ביין],\u0006 שהרי יש להם שימושים שונים.","במשנה זו מבוארים כמה מדרכי הקנין של מיטלטלים. \u0003המוכר פירות לחבירו,\u0004 אם \u0003משך\u0004 הקונה את הפירות \u0003ולא מדד\u0004 עדיין — הרי זה \u0003קנה\u0004 במשיכה, אבל אם \u0003מדד ולא משך\u0004 — \u0003לא קנה\u0004 בכך ויכולים המוכר והקונה עדיין לחזור בהם. ו\u0003אם היה\u0004 הקונה \u0003פיקח\u0004 ורוצה לגמור את המיקח קודם שיתחרט המוכר — \u0003שוכר את מקומן\u0004 של הפירות הללו, והריהם עתה ברשותו ונקנו לו בכך מאותה שעה כאילו היו בחצירו.","\u0003הלוקח\u0004 (קונה) \u0003פשתן\u0004 שדרך לטלטלו ביד \u0003מחבירו\u0004 — \u0003הרי זה לא קנה\u0004 במשיכה סתם על גבי הקרקע, \u0003עד שיטלטלנו ממקום למקום\u0004 ויקנהו בדרך הגבהה. \u0003ואם היה מחובר לקרקע ותלש כל שהוא\u0004 — \u0003קנה.\u0004 ובגמרא יבואר משפט סתום זה.","במשנה נזכרו כמה דרכי קנין, אך לא נתפרשו בה פרטים רבים — באיזו רשות אירעו הדברים (כגון אם במקום ציבורי או ברשות המוכר), וכן לא נתפרש מי הוא העושה פעולות אלה. ומבררים פרטים אלה. \u0003אמר ר' אסי אמר ר' יוחנן: מדד\u0004 המוכר \u0003והניח על גבי סימטא\u0004 (שאינה רשות הרבים, אלא מקום שבו רשאים אנשים שונים להניח את חפציהם), למרות שהקונה לא משך — \u0003קנה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא לר' אסי\u0004 בשאלה על שמועתו זו: \u0003שמא לא שמע רבי\u0004 הלכה זו מר' יוחנן \u0003אלא במודד לתוך קופתו\u0004 של הקונה, שאז קונים כליו בסימטא, ולא על גבי קרקע הסימטא? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003דמי האי מרבנן כדלא גמרי אינשי שמעתא\u0004 \u0005[דומה זה מן החכמים,\u0006 אתה, \u0005כאנשים שלא למדו הלכה],\u0006 וכי \u0003מדד לתוך קופתו מימרא בעי\u0004 \u0005[צריך לומר]\u0006 שקונה בסימטא? והרי מה שנכנס לתוך קופתו של הקונה נקנה לו בכל מקום! ואם כן, דברי ר' יוחנן בסימטא נאמרו במקרה שמניח על גבי קרקע הסימטא.","ושואלים: האם \u0003קיבלה\u0004 ר' זירא הלכה זו \u0003מיניה\u0004 \u0005[ממנו\u0006 מר' אסי\u0005]\u0006 והסכים לה, \u0003או לא קיבלה מיניה\u0004 \u0005[ממנו]?\u0006 ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה מה ש\u0003אמר ר' ינאי אמר רבי: חצר השותפין\u0004 (שדינה דומה לסימטא) — \u0003קונין\u0004 בה השותפים \u0003זה מזה; מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר פה שקונים אפילו כשמניחים \u0003על גבי קרקע,\u0004 וכדברי ר' אסי? שהרי לא חילקו בדבר. ודוחים: \u0003לא,\u0004 הכוונה היא דווקא כשמודד \u0003לתוך קופתו\u0004 של הקונה.","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר],\u0006 לומר כדברי ר' זירא, ש\u0003אמר ר' יעקב אמר ר' יוחנן: מדד והניח על גבי סימטא\u0004 — \u0003לא קנה,\u0004 ולכאורה \u0003קשיין אהדדי\u0004 \u0005[קשות\u0006 שתי ההלכות הללו שבשמו של ר' יוחנן \u0005זו על זו],\u0006 שהרי קודם אמרנו בשם ר' יוחנן שקנה! \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 ש\u0003כאן\u0004 בדברי ר' אסי מדובר \u0003במודד לתוך קופתו\u0004 ולכן קנה, \u0003כאן\u0004 בדברי ר' יעקב מדובר \u0003במודד על גבי קרקע\u0004 ולכן לא קנה? ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר זה ממה ששנינו במשנתנו: \u0003מדד ולא משך\u0004 — \u0003לא קנה; מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר \u0003בסימטא?\u0004 משמע שהנחה על גבי קרקע הסימטא בלבד אינה קונה, וכדברי ר' זירא! ודוחים: \u0003לא,\u0004 כאן מדובר \u0003ברשות הרבים.\u0004 ושואלים: \u0003אי הכי, אימא רישא\u0004 \u0005[אם כך, אמור את ראשה\u0006 של המשנה\u0005]:\u0006 \u0003משך ולא מדד\u0004 — \u0003קנה;\u0004 וכי \u0003משיכה ברשות הרבים מי קניא\u0004 \u0005[האם\u0006 היא \u0005קונה]?\u0006","\u0003והא\u0004 \u0005[והרי]\u0006 \u0003אביי ורבא דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003מסירה קונה ברשות הרבים ו\u0004כן \u0003בחצר שאינה של שניהן, משיכה קונה\u0004 רק \u0003בסימטא ובחצר שהיא של שניהן\u0004 ולא ברשות הרבים, \u0003והגבהה קונה בכל מקום,\u0004 אפילו ברשות המוכר!","ומשיבים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"משך\" נמי דקתני\u0004 \u0005[גם כן ששנינו\u0006 במשנה\u0005]?\u0006 — כוונתו שמשך \u0003מרשות הרבים לסימטא.\u0004 ומקשים: \u0003אי הכי, אימא סיפא\u0004 \u0005[אם כך, אמור\u0006 את \u0005סופה\u0006 של המשנה\u0005]:\u0006 \u0003אם היה פיקח\u0004 — \u0003שוכר את מקומן; ואי\u0004 \u0005[ואם]\u0006 מדובר \u0003ברשות הרבים, ממאן אגר\u0004 \u0005[ממי\u0006 הוא \u0005שוכר]\u0006 את מקומם של הפירות? ומשיבים: כאן מדובר בהלכה נפרדת, ו\u0003הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 \u0003ואם ברשות בעלים היא,\u0004 שיש למקום זה בעלים, \u0003אם היה פיקח\u0004 — \u0003שוכר את מקומן.\u0004","ועוד בענייני קנין. \u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006"],["\u0003כליו של אדם קונה\u0004 (קונים) \u0003לו\u0004 מה שבא לתוכם \u0003בכל מקום\u0004 בו הם נמצאים, \u0003חוץ מרשות הרבים\u0004 ששם אינו יכול לקנות אפילו בתוך כליו, \u0003ור' יוחנן ור' שמעון בן לקיש דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003אפילו ברשות הרבים.\u0004","\u0003אמר רב פפא, לא פליגי\u0004 \u0005[אין\u0006 הם \u0005חלוקים]:\u0006 \u0003כאן\u0004 בדברי רב ושמואל, שאין כליו של הקונה קונים לו, מדובר \u0003ברשות הרבים\u0004 ממש, \u0003כאן\u0004 בדברי ר' יוחנן וריש לקיש, שקונה הלוקח בכליו, מדובר \u0003בסימטא. ואמאי קרו\u0004 \u0005[ומדוע קוראים]\u0006 \u0003לה\u0004 לסימטא \u0003רשות הרבים?\u0004 הרי זה לומר: רשות \u0003שאין\u0004 היא \u0003רשות היחיד.\u0004","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לומר ולהבין את דברי ר' יוחנן, שהרי כך \u0003אמר ר' אבהו אמר ר' יוחנן: כליו של אדם קונה לו בכל מקום שיש לו רשות להניחו.\u0004 ונדייק מכאן: \u0003יש לו רשות\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003אין לו רשות\u0004 — \u0003לא\u0004 קונה לו, וברשות הרבים ממש הרי אין לו רשות להניח, אלא בסימטא. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שזהו מובנה של רשות הרבים האמורה בדברי ר' יוחנן.","ומקשים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בברייתא: \u0003ארבע מדות במוכרין,\u0004 כלומר, ארבעה אופנים בהם נקנה המכר: מדד המוכר לקונה, \u0003עד שלא\u0004 (טרם) \u0003נתמלאה\u0004 כלי ה\u0003מדה\u0004 — הרי מה שבתוכה שייך עדיין \u0003למוכר,\u0004 שיכול לחזור בו אם ירצה, \u0003משנתמלאה\u0004 כלי ה\u0003מדה\u0004 — הרי זה שייך \u0003ללוקח. במה דברים אמורים\u0004 — כאשר מודד \u0003במדה ש\u0004היא עצמה \u0003אינה של שניהן, אבל אם היתה מדה של אחד מהן\u0004 — \u0003ראשון ראשון\u0004 שנכנס למידה — \u0003קנה.\u0004","\u0003במה דברים אמורים\u0004 — כאשר מודד \u0003ברשות הרבים ובחצר שאינה של שניהן, אבל ברשות מוכר\u0004 — \u0003לא קנה\u0004 הלוקח אף בכליו \u0003עד שיגביהנה\u0004 (את המידה) \u0003או עד שיוציאנה מרשותו.\u0004 ואם היה הדבר \u0003ברשות לוקח, כיון שקבל עליו\u0004 ה\u0003מוכר\u0004 למכור — \u0003קנה\u0004 ה\u0003לוקח.\u0004 ואם היה הדבר \u0003ברשות הלה\u0004 \u0003המופקדים אצלו,\u0004 שהיו הדברים המכורים מונחים אצל אדם אחר כפקדון — \u0003לא קנה\u0004 הקונה \u0003עד שיקבל עליו\u0004 השומר לייחד ללוקח את מקום הפירות, \u0003או עד שישכור את מקומן\u0004 מן השומר.","\u0003קתני מיהא\u0004 \u0005[שנה על כל פנים]\u0006 דרך קנין בכלי הלוקח \u0003ברשות הרבים ובחצר שאינה של שניהן;\u0004"],["\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר פה \u0003ברשות הרבים ממש?\u0004 ומשמע מכאן שאף ברשות הרבים קונים כליו של לוקח, שלא כפי שתירץ רב פפא לעיל! ודוחים: \u0003לא,\u0004 הכוונה כאן אינה לרשות הרבים ממש, אלא ל\u0003סימטא.\u0004 ומקשים: כיצד יכול אתה לפרש כן? \u0003והא דומיא\u0004 \u0005[והרי בדומה]\u0006 ל\u0003חצר שאינה של שניהם קתני\u0004 \u0005[שנה]\u0006 שאין למוכר ולקונה כלל רשות בה, ואילו סימטא — יש בה רשות לשניהם!","ומשיבים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"חצר שאינה של שניהם\" נמי\u0004 \u0005[גם כן]?\u0006 חצר השותפים, ש\u0003לא דהאי\u0004 \u0005[של זה]\u0006 \u0003כולה ולא דהאי\u0004 \u0005[של זה]\u0006 \u0003כולה, אלא דתרוייהו\u0004 \u0005[של שניהם]\u0006 והריהי איפוא בדומה לסימטא.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רב ששת מרב הונא: כליו של לוקח\u0004 המונחים \u0003ברשות מוכר,\u0004 האם \u0003קנה לוקח\u0004 משהוכנסו הדברים הנקנים לתוכם, \u0003או לא? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003תניתוה\u0004 \u0005[\u0006כבר \u0005שניתם אותה],\u0006 שיש פתרון לשאלה זו ממה ששנינו לגבי גט, שהגירושים חלים כאשר מוסרו הבעל ליד אשתו, או לדבר הנחשב כידה, כגון חצרה. ואמרו: \u0003זרקו לה\u0004 הבעל לאשתו את הגט \u0003לתוך חיקה או לתוך קלתה\u0004 (הסל שלה) — \u0003הרי זו מגורשת,\u0004 כיון שהיא קונה את הגט המצוי בתוך הסל שלה, אף על פי שהוא ברשות הבעל. ונמצא שכליו של לוקח ברשות מוכר — קנה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן\u0004 לרב הונא: \u0003מאי טעמא פשטת ליה\u0004 \u0005[מה טעם פתרת לו]\u0006 לרב ששת את שאלתו \u0003מ\u0004מה ששנינו במשנה \u0003ההיא, דמחו לה\u0004 \u0005[ש\u0006כבר \u0005היכו\u0006 \u0003אותה]\u0004 \u0003מאה עוכלי בעוכלא\u0004 \u0005[מכות במשקולת]?\u0006 שכבר דנו עליה חכמים, וסייגו אותה בכל כך הרבה סייגים, עד שאינה מתפרשת עוד כמשמעה.","ומביאים מה שנאמר עליה, \u0003אמר רב יהודה אמר שמואל: ו\u0004דין זה \u0003הוא\u0004 רק כ\u0003שהיתה קלתה תלויה בה,\u0004 ולכן היא נחשבת כמונחת עליה או בידה, \u0003וריש לקיש אמר:\u0004 די בכך שהיתה \u0003קשורה ואף על פי שאינה תלויה בה\u0004 אלא נגררת על הארץ. ו\u0003רב אדא בר אהבה אמר: כגון שהיתה קלתה מונחת לה בין ירכותיה,\u0004 שאף שאינה תלויה עליה, כיון שהיא מונחת על גופה, בוודאי נקנה לה בה. \u0003רב משרשיא בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' אמי אמר: כגון שהיה בעלה מוכר קלתות,\u0004 ולכן אינו מקפיד על קלתות שנמצאות בחצירו, והרי זה כאילו נתן לה את מקום הקלת שיהא שלה.","\u0003ר' יוחנן אמר:\u0004 בכלל, \u0003מקום חיקה,\u0004 כלומר, מקום שבו היא עומדת או יושבת, \u0003קנוי לה\u0004 לאשה, וכן \u0003מקום קלתה קנוי לה\u0004 לאשה. ועל כך \u0003אמר רבא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יוחנן? לפי שאין אדם מקפיד לא על מקום חיקה ולא על מקום קלתה,\u0004 כיון שהיא זקוקה להם ואינם תופסים מקום מרובה. ומכל מקום ברור שאין ללמוד מהלכה זו הלכה כללית לגבי כליו של קונה ברשות מוכר. ואם כן אין מקום להביא הוכחה מהלכה זו.","\u0003אלא פשוט לה מהא\u0004 \u0005[פתור א\u0006 \u0005ותה\u0006 שאלה ששאל רב ששת \u0005מזו],\u0006 ששנינו בברייתא שהבאנו: \u0003ברשות מוכר\u0004 — \u0003לא קנה עד שיגביהנה או עד שיוציאנה מרשותו; מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר פה \u0003בכליו\u0004 של \u0003לוקח?\u0004 ומכאן משמע שכליו של לוקח ברשות מוכר אינם קונים! ודוחים: \u0003לא,\u0004 מכאן אין פתרון משום שמדובר פה \u0003בכליו\u0004 של \u0003מוכר,\u0004 ולכן צריך הקונה להגביהם או למושכם.","ומקשים: \u0003ומדרישא\u0004 \u0005[ו\u0006מתוך \u0005שראשה,\u0006 תחילתה\u0005]\u0006 של המשנה מתפרש שמדובר בו \u0003בכליו\u0004 של \u0003מוכר,\u0004 \u0003סיפא נמי\u0004 \u0005[בסופה גם כן]\u0006 מדובר \u0003בכליו\u0004 של \u0003מוכר,\u0004 ואולם \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה\u0006 של הברייתא\u0005],\u0006 ששנינו בה: אם היה זה \u0003ברשות לוקח, כיון שקיבל עליו\u0004 ה\u0003מוכר\u0004 למכור — \u0003קנה\u0004 ה\u0003לוקח; ואי\u0004 \u0005[ואם]\u0006 מדובר, כמו בדין הראשון, \u0003בכליו\u0004 של ה\u0003מוכר, אמאי\u0004 \u0005[מדוע]\u0006 \u0003קנה\u0004 ה\u0003לוקח?\u0004 ומתרצים: \u0003סיפא אתאן\u0004 \u0005[בסוף\u0006 המשנה \u0005באים אנו]\u0006 למקרה אחר, בו הכלים הם \u0003כליו\u0004 של \u0003לוקח.\u0004","ותוהים: \u0003ומאי פסקא\u0004 \u0005[ומה הפסק]?\u0006 כלומר, מהיכן באה פסיקה וחיתוך זה? ומשיבים: יש טעם בדבר, שכן \u0003סתמא דמילתא\u0004 \u0005[סתמו של דבר],\u0006 \u0003בי\u0004 \u0005[\u0006ב\u0005בית]\u0006 ה\u0003מוכר מאני\u0004 \u0005[הכלים]\u0006 של ה\u0003מוכר שכיחי\u0004 \u0005[מצויים],\u0006 \u0003בי\u0004 \u0005[\u0006ב\u0005בית]\u0006 ה\u0003לוקח מאני\u0004 \u0005[הכלים]\u0006 של ה\u0003לוקח שכיחי\u0004 \u0005[מצויים].\u0006 ובסיכום — אין להביא מכאן ראיה לצד זה או אחר.","\u0003אמר רבא, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה, ממה ששנינו: \u0003משך\u0004 הקונה \u0003חמריו\u0004 (מוליכי חמוריו) של המוכר וחמורים עמוסים אחריהם, \u0003ו\u0004כן אם משך \u0003פועליו\u0004 שהיו עמוסים בדברים שרצונו לקנות, \u0003והכניסן לתוך ביתו, בין\u0004 אם \u0003פסק\u0004 (קצב מחיר) \u0003עד שלא\u0004 (טרם) \u0003מדד\u0004 את הסחורה, \u0003ובין\u0004 אם \u0003מדד עד שלא פסק\u0004 — כל עוד המיטלטלים על גבי הפועלים או החמורים, הרי \u0003שניהן,\u0004 בין הקונה ובין המוכר, \u0003יכולין לחזור בהן.\u0004"]]};
